// Node.js roadmap questions (200): 25 levels × 8, easiest → hardest. Authored as
// a single 8-per-level list and built directly (like Git/HTML/CSS), so each
// 5-level checkpoint covers a full 40-question pool. See lib/roadmap.ts for the
// level titles.

import type { Seed } from './roadmap-build';

export const nodeSeeds: Seed[] = [
  // ── Level 1 — Node Basics ──────────────────────────────────────────────
  { q: 'What is Node.js?', opts: ['A web browser', 'A JavaScript runtime built on the V8 engine', 'A CSS framework', 'A database server'], a: 1, e: 'Node.js is a runtime: it embeds Chrome’s V8 engine and adds libraries for files, networking and processes, so JavaScript can run outside a browser page. It is not a browser (it has no DOM), not a CSS framework, and not a database, although Node programs commonly talk to databases.', intro: 'You install Node and start it from a terminal with `node app.js`; ask which category of software can execute a JavaScript file that way.', tags: ['Node', 'Basics'] },
  { q: 'Where does Node.js let you run JavaScript?', opts: ['In a browser tab, as page scripts', 'Outside the browser, e.g. on a server', 'Inside an HTML file, as inline scripts', 'Inside a mobile app, in a web view'], a: 1, e: 'Node runs JavaScript directly on a machine — a server, a laptop, a CI runner — with no browser involved; that is how npm, Vite and an Express server work. It does not run inside a browser tab, an HTML page or a mobile web view; those environments bring their own JavaScript engines. Node can also run a script piped in on stdin.', intro: 'npm, Vite and an Express server are all written in JavaScript; ask where each one runs when you use it.', tags: ['Node', 'Basics'] },
  { q: 'Which JavaScript engine powers Node.js?', opts: ['SpiderMonkey', 'Chakra', 'V8', 'JavaScriptCore'], a: 2, e: 'Node.js embeds V8, the open-source engine from Chrome, and adds its own APIs around it; that is why new JavaScript features reach Node as V8 updates land (check process.versions.v8). SpiderMonkey powers Firefox and JavaScriptCore powers Safari; Chakra was the engine of the old Edge, and a Node build on it was discontinued.', intro: 'Node was built on the engine of one particular browser; recall which browser Node shares its JavaScript engine with.', tags: ['Node', 'Basics'] },
  { q: 'How is JavaScript execution modeled in Node?', opts: ['Multi-threaded by default', 'Single-threaded with an event loop', 'One process per request', 'No concurrency at all'], a: 1, e: 'Your JavaScript runs on one main thread; an event loop dispatches callbacks as timers fire and I/O completes, so one thread can serve many connections. Node is not multi-threaded by default (worker_threads are opt-in and libuv’s pool stays internal), it does not fork a process per request, and it clearly has concurrency — just not parallel JavaScript.', intro: 'Ask two things: how many threads execute your JavaScript callbacks, and what mechanism hands that thread new work as operations complete.', tags: ['Node', 'Basics'] },
  { q: 'What does the --watch flag add to this command?\n\n```bash\n$ node --watch app.js\n```', opts: ['It compiles app.js to a native binary before running', 'It executes app.js and restarts when watched files change', 'It opens app.js in the default editor after each change', 'It installs packages imported by app.js'], a: 1, e: '`--watch` runs app.js and, whenever app.js or a module it imports changes, kills and restarts the process — the job nodemon used to do; it runs without an experimental warning in Node 22. Node does not compile to a native binary here (that is the separate single-executable feature), does not open an editor, and does not install packages (that is npm’s job).', intro: 'Compare with plain `node app.js` and ask what could change while the program keeps running; this flag replaces a common third-party dev tool.', tags: ['Node', 'Basics'] },
  { q: 'Which I/O model do Node’s core APIs use by default (for example fs.readFile and network sockets)?', opts: ['Blocking, synchronous I/O', 'Non-blocking, event-driven I/O', 'One thread per connection', 'Polling-only I/O'], a: 1, e: 'Node’s core APIs start an operation, return immediately, and deliver the result later through a callback, promise or event — non-blocking, event-driven I/O — so one thread keeps serving other work while the disk or network is busy. Node also offers blocking *Sync variants, but they are the exception; it does not dedicate a thread to each connection, and it does not spin polling for results: libuv sleeps until the operating system (or, for file reads, its thread pool) reports completion.', intro: 'Recall what happens while a file read is in flight: does your program wait for it, or carry on and get called back later?', tags: ['Node', 'Basics'] },
  { q: 'Which of these globals exists in browsers but is not defined in Node.js?', opts: ['console', 'setTimeout', 'document', 'Math'], a: 2, e: 'Node has no DOM, so `document` (and `window`) are undefined; `Math` is a language built-in, and `console` and `setTimeout` are provided by both browsers and Node. Node does ship some browser-style globals (fetch, URL, a partial navigator), but nothing that represents a page.', intro: 'Node has no page to render. Decide which global is tied to a page rather than to the JavaScript language or its timers.', tags: ['Node', 'Basics'] },
  { q: 'In an interactive terminal, what does running `node` with no arguments start?', opts: ['A web server', 'An interactive REPL', 'A file watcher', 'The package manager'], a: 1, e: 'Plain `node` in a terminal opens the REPL (Read-Eval-Print Loop), where each line you type is evaluated and its result printed — handy for trying an API. If stdin is not a terminal (for example `echo "code" | node`), Node reads a script from stdin instead. A server, file watching (`--watch`) and package management (npm) all need explicit commands.', intro: 'With no file to run but a terminal attached, Node still has to do something with the JavaScript you type. Think about what that mode is called.', tags: ['Node', 'Basics'] },

  // ── Level 2 — Modules (CommonJS) ───────────────────────────────────────
  { q: 'In CommonJS, how do you import another module?', opts: ['import x from "x"', 'require("x")', 'include("x")', 'load("x")'], a: 1, e: 'CommonJS loads modules with `require(id)`, an ordinary function call that returns the module’s exports, so it can appear anywhere in the code. `import x from "x"` is ES module syntax, which a CommonJS file cannot use; `include` and `load` do not exist in Node.', intro: 'CommonJS predates the `import` keyword. Recall the function call Node’s own docs use to load a module into a variable.', tags: ['Node', 'Modules'] },
  { q: 'How do you export a value in CommonJS?', opts: ['export default value', 'module.exports = value', 'return value', 'global.value'], a: 1, e: 'Assigning to `module.exports` sets the value `require()` returns for that file; you can also attach properties with `exports.name = ...`. `export default` is ES module syntax, a top-level `return` is legal in CommonJS (the file is wrapped in a function) but only stops execution and exports nothing, and putting values on `global` leaks them to every module instead of exporting them.', intro: 'Think about what `require()` hands back to the caller, then ask which statement sets that value from inside the module.', tags: ['Node', 'Modules'] },
  { q: 'What does require() return?', opts: ['Always undefined', 'The loaded module’s module.exports', 'A Promise', 'The file path'], a: 1, e: '`require()` loads the module synchronously (once — later calls hit the cache) and returns whatever that module assigned to `module.exports`, often an object or a function; a module that exports nothing yields `{}`, not undefined. It never returns a Promise (that is dynamic `import()`), and it does not return the file path — `require.resolve()` does that.', intro: 'Follow the value across the boundary: whatever the module assigns on its side is exactly what the caller receives. Ask which object carries it.', tags: ['Node', 'Modules'] },
  { q: 'Are CommonJS modules cached after the first require?', opts: ['No, re-read every time', 'Yes, the same instance is reused', 'Only in production', 'Only for core modules'], a: 1, e: 'Node caches each module by resolved filename in `require.cache`: the module code runs once and every later `require()` returns the same exports object, in every environment and for user modules as well as core modules. Deleting the cache entry forces a fresh load (rarely a good idea), and a specifier that resolves to a different filename (a different letter case on a case-insensitive file system, or a second copy inside another node_modules folder) produces a separate instance.', intro: 'Consider a module that opens a database connection at load time and is required from ten files. Decide how many times Node runs it.', tags: ['Node', 'Modules'] },
  { q: 'What does `__dirname` contain?', opts: ['The directory the process was started from', 'The absolute path of the directory containing the current module', 'The absolute path of the current module file itself', 'The project root read from package.json'], a: 1, e: '`__dirname` is the absolute path of the directory containing the current CommonJS module file, unaffected by where the process was launched (that is `process.cwd()`); the file’s own path is `__filename`, and Node has no notion of a project root. In ES modules `__dirname` is not defined at all (reading it throws a ReferenceError); use `import.meta.dirname` (Node 20.11+, stable since 22.16) instead.', intro: 'Two different questions hide here: where the process was started, and where this file lives. Decide which one `__dirname` answers.', tags: ['Node', 'Modules'] },
  { q: 'What does `require("./utils")` load?', opts: ['An npm package', 'A local file module named utils', 'A built-in core module', 'A remote URL'], a: 1, e: 'A specifier starting with `./` (or `../`) is resolved relative to the directory of the requiring module: Node tries utils.js, utils.json and utils.node, then utils/index.js. Bare names such as "lodash" are searched in node_modules and bare core names such as "fs" load built-ins; CommonJS `require` never fetches remote URLs.', intro: 'Look at the first two characters of the specifier: they tell Node whether to search node_modules, the built-in list, or the file system next to this module.', tags: ['Node', 'Modules'] },
  { q: 'Why can reassigning `exports = {…}` fail to export?', opts: ['It throws an error', 'It breaks the reference to module.exports', 'exports is read-only', 'It exports twice'], a: 1, e: 'Node passes `exports` into the module wrapper as a reference to `module.exports`; `exports = {...}` rebinds only that local variable, so `module.exports` stays `{}` and `require()` returns an empty object — no error is thrown and nothing is read-only. Adding properties (`exports.x = 1`) or assigning to `module.exports` works because both change the object Node actually returns.', intro: 'Inside a module, `exports` starts as a shortcut to another object. Ask what a plain `=` does to a shortcut, versus setting a property on it.', tags: ['Node', 'Modules'] },
  { q: 'What does `require("fs")` load?', opts: ['A local file', 'The built-in file-system core module', 'An npm dependency', 'A JSON file'], a: 1, e: 'A bare name that matches a built-in (fs, path, http…) loads the core module compiled into Node, taking priority over any node_modules package with the same name; the `node:fs` form makes that explicit. `./`-prefixed specifiers load local files, and JSON is loaded only when the path points at a .json file.', intro: 'The specifier has no `./` and no path. Decide what Node checks first for a bare name like this, before it looks in node_modules.', tags: ['Node', 'Modules'] },

  // ── Level 3 — ES Modules ───────────────────────────────────────────────
  { q: 'Which line correctly imports the default export of `./x.js` in a Node ES Module?', opts: ['require("./x")', 'import x from "./x.js"', 'import "./x.js" as x', 'from "./x.js" import x'], a: 1, e: '`import x from "./x.js"` is the static import declaration: the local binding, then `from`, then a specifier that in Node must carry the `.js` extension. `require("./x")` is CommonJS and is not defined inside an ES module, while `import "./x.js" as x` and `from "./x.js" import x` reorder the keywords into grammar ESM does not accept.', intro: 'Recall the order of the keywords in the statement, and that Node\'s specifier keeps the file extension.', tags: ['Node', 'ESM'] },
  { q: 'How do you make .js files use ES Modules in a package?', opts: ['Set "type": "module" in package.json', 'Rename to .cjs', 'Add "use esm"', 'Nothing is needed'], a: 0, e: '`"type": "module"` in the nearest package.json makes every `.js` file in that package load as an ES Module; without it Node reads `.js` as CommonJS and an `import` statement fails with "Cannot use import statement outside a module". Renaming to `.cjs` does the opposite, pinning a single file to CommonJS, and there is no `"use esm"` directive in Node.', intro: 'Node decides a file\'s module system before it parses the file, so a directive written inside the file comes too late.', tags: ['Node', 'ESM'] },
  { q: 'Which file extension does Node always load as an ES Module, whatever package.json "type" says?', opts: ['.cjs', '.mjs', '.js', '.json'], a: 1, e: '`.mjs` is always parsed as an ES Module and `.cjs` is always CommonJS, so both override the package\'s `"type"` field. `.js` is the extension that defers to `"type"` (ESM when it is `"module"`, CommonJS otherwise), and `.json` is loaded as data rather than as a module of either kind.', intro: 'Two of these extensions decide the module system by themselves; one defers to package.json and one is not code at all.', tags: ['Node', 'ESM'] },
  { q: 'What is a named export in ESM?', opts: ['export default fn', 'export const x = 1', 'module.exports.x = 1', 'global.x = 1'], a: 1, e: '`export const x = 1` is a named export: the importer writes `import { x } from "./mod.js"` and gets that exact identifier. `export default fn` exports a single value the importer may rename at will, so no name is part of the contract. `module.exports.x = 1` is CommonJS syntax rather than ESM (Node\'s interop can still expose `x` to an ESM importer), and `global.x = 1` only sets a property on the global object, which no `import` statement reads.', intro: 'Ask what the importing module has to type to get the value, and whether it is free to choose a different word.', tags: ['Node', 'ESM'] },
  { q: 'In a Node ES Module, how are `import` declarations processed?', opts: ['Dynamically: resolved when that line executes', 'Statically: resolved and hoisted before the module body runs', 'Conditionally: they may be placed inside `if` blocks', 'Asynchronously: each one returns a promise you await'], a: 1, e: 'Import declarations belong to the module\'s static structure: Node resolves and evaluates every imported module before the importing module\'s own body runs, which is why an `import` must sit at the top level and a conditional one is a SyntaxError. The function-call form `import()` is the dynamic counterpart, and it alone resolves at the moment it executes and returns a promise.', intro: 'Put a `console.log` on line 1 and an `import` on line 2, then ask which output appears first.', tags: ['Node', 'ESM'] },
  { q: 'Can you call `require()` directly inside an ES Module?', opts: ['Yes — `require` exists in every Node module', 'No — `require` is undefined there; use `import` or `createRequire`', 'Yes — but only for `.json` files', 'Yes — but only after an `await import()`'], a: 1, e: 'Node injects `require`, `module`, `exports`, `__dirname` and `__filename` into the CommonJS module wrapper; an ES module gets no wrapper, so calling `require()` there fails with `ReferenceError: require is not defined in ES module scope`. Use `import`, static or dynamic, or build a loader with `createRequire(import.meta.url)` when you must load a CommonJS-only package by path. Awaiting a dynamic `import()` first changes nothing, since it never defines `require`, and JSON is loaded with `import data from "./d.json" with { type: "json" }`.', intro: '`require` is injected by the CommonJS module wrapper. Ask whether an ES module is wrapped at all.', tags: ['Node', 'ESM'] },
  { q: 'What is the default export syntax in ESM?', opts: ['export default value', 'module.exports = value', 'export value', 'default export value'], a: 0, e: '`export default value` marks the module\'s single default export; the importer writes `import anything from "./mod.js"` and may pick any local name. `module.exports = value` is the CommonJS equivalent, and although Node\'s interop hands that value to an ESM default import, it is not ESM syntax. `export value` and `default export value` are both SyntaxErrors, because a bare `export` must be followed by `default`, a declaration, or braces.', intro: 'Two keywords in a fixed order, then the value. Recall which keyword the ESM grammar requires first.', tags: ['Node', 'ESM'] },
  { q: 'Is top-level await allowed in an ES Module?', opts: ['No — `await` is valid only inside an `async` function', 'Yes — `await` may appear at the top level of the module', 'Yes — but only inside `.cjs` files', 'Yes — but only when the module has no exports'], a: 1, e: 'An ES module can await at the top level: Node treats such a module as asynchronous and holds every importer until it settles before running their bodies. CommonJS cannot, because `require()` has to return synchronously — the same line in a `.cjs` file is a SyntaxError, which is why the `.cjs` option is backwards.', intro: 'Think about what an importing module would have to do while this module is still waiting on a promise.', tags: ['Node', 'ESM'] },

  // ── Level 4 — Globals & process ────────────────────────────────────────
  { q: 'What is the global object in Node?', opts: ['window', 'global (a.k.a. globalThis)', 'self', 'document'], a: 1, e: 'Node\'s top-level object is reachable as `globalThis`; the Node-only alias `global` refers to the same object but the Node 22 documentation marks it Stability 3 (Legacy) and recommends `globalThis`, which also works in browsers and workers. `window`, `self` and `document` come from browser environments and are all undefined in Node.', intro: 'Ask which of these names you could print from a plain `node -e` one-liner without a ReferenceError.', tags: ['Node', 'Globals'] },
  { q: 'What does `process.argv` contain?', opts: ['Environment variables', 'The command-line arguments', 'The exit code', 'The current directory'], a: 1, e: '`process.argv` is an array of strings: index 0 is the Node executable path, index 1 is the resolved script path, and your own arguments start at index 2 — which is why CLI code usually begins with `process.argv.slice(2)`. Environment variables live in `process.env`, the exit status in `process.exitCode`, and the working directory comes from `process.cwd()`.', intro: 'You ran `node app.js --port 3000`. Ask which of these four things changed when you typed `--port 3000`.', tags: ['Node', 'process'] },
  { q: 'What is `process.env`?', opts: ['The event loop', 'An object of environment variables', 'The process id', 'The argument list'], a: 1, e: '`process.env` is the object holding the environment variables the process was started with, which is where configuration and secrets normally arrive. Every value is a string, so a `DEBUG` variable set to `"false"` is still a non-empty string and therefore truthy; you have to compare it explicitly. Command-line arguments are in `process.argv`, the process id in `process.pid`, and the event loop is not an object you read from `process` at all.', intro: 'Think of what the shell passes to a program that is not a command-line argument — the settings a deployment sets outside the code.', tags: ['Node', 'process'] },
  { q: 'What does `process.exit(0)` do?', opts: ['Restarts the Node process with the same arguments', 'Ends the process immediately with a success status', 'Stops the event loop but leaves the process running', 'Signals success and waits for pending I/O to finish'], a: 1, e: '`process.exit(0)` ends the process at once with exit status 0, the convention for success. It does not drain pending work: queued callbacks are dropped and buffered writes to a pipe can be truncated, which is why the safer pattern is to set `process.exitCode = 0` and let the event loop finish on its own.', intro: 'Zero is the conventional success status. The harder half of the question is the word "immediately" — decide what happens to work still in flight.', tags: ['Node', 'process'] },
  { q: 'What does `process.cwd()` return?', opts: ['The script’s folder', 'The current working directory', 'The home directory', 'The temp directory'], a: 1, e: '`process.cwd()` returns the process\'s current working directory — normally the directory you launched Node from, though `process.chdir()` can change it mid-run. It is not the script\'s folder: that is `__dirname` (or `import.meta.dirname` in ESM), and the two differ whenever you run `node subdir/app.js` from somewhere else, which is why relative `fs` paths resolve against the caller\'s location rather than the code\'s.', intro: 'Two of these can differ on the very same run: where you were standing when you typed `node`, and where the file itself lives.', tags: ['Node', 'process'] },
  { q: 'Where does `console.log` write by default?', opts: ['A log file', 'stdout', 'stderr', 'The network'], a: 1, e: '`console.log` writes to `process.stdout`; `console.error` and `console.warn` write to `process.stderr`. The split matters when a program\'s output is piped: `node app.js > data.json` captures only the `console.log` lines and lets diagnostics still reach the terminal. Node writes to neither a file nor the network unless you attach a stream that does.', intro: 'Two of these are real console destinations in Node, and the console method you pick decides which. Recall which one `log` uses.', tags: ['Node', 'Globals'] },
  { q: 'Code chooses a Windows-specific executable only when `process.platform === "win32"`. What does process.platform represent?', opts: ['The installed Node release line', 'The operating-system platform identifier', 'The processor architecture and core count', 'The machine’s network hostname'], a: 1, e: '`process.platform` is the operating-system identifier: `"win32"`, `"linux"`, `"darwin"`, `"freebsd"` and so on. Note that `"win32"` is returned on 64-bit Windows as well, so it means Windows rather than 32-bit. The other options are different properties: the Node release line is `process.version`, the CPU architecture is `process.arch` (with core count from `os.cpus()`), and the hostname comes from `os.hostname()`.', intro: 'The scenario branches on one string. Decide what kind of fact a value like "win32" is reporting about the machine.', tags: ['Node', 'process'] },
  { q: 'Which of these identifiers is NOT available to code in a Node CommonJS module?', opts: ['__dirname', 'process', 'window', 'Buffer'], a: 2, e: '`window` is defined by browsers, not by Node, so referencing it in Node throws a ReferenceError. `process` and `Buffer` are true globals on `globalThis`, while `__dirname` is not a global at all — Node injects it into the CommonJS module wrapper, which is why it exists in a `.cjs` file and is undefined in an ES module.', intro: 'Node has no page and no DOM. Ask which of these names you would only ever meet in code running inside a browser.', tags: ['Node', 'Globals'] },

  // ── Level 5 — The Event Loop ───────────────────────────────────────────
  { q: 'What does the event loop enable?', opts: ['JavaScript to run on several threads at once', 'One thread to keep serving work while I/O is pending', 'CPU-bound loops to finish without blocking anything', 'Callbacks to run in the order they were created'], a: 1, e: 'The event loop gives concurrency, not parallelism: your JavaScript stays on one thread, and while an I/O operation is outstanding that thread is free to run other callbacks, so thousands of connections can be in flight at once. It does nothing for CPU-bound work — a long computation still blocks everything — and callbacks run when their phase and queue say so, not in the order they were created.', intro: 'Concurrency and parallelism are not the same thing. Ask which of the two a single thread can offer.', tags: ['Node', 'EventLoop'] },
  { q: 'A `setTimeout` callback runs in which event-loop phase?', opts: ['The poll phase', 'The timers phase', 'The close phase', 'The idle phase'], a: 1, e: 'Expired `setTimeout` and `setInterval` callbacks run in the timers phase. The other options name real phases with other jobs: poll is where Node waits for and runs I/O callbacks, check is where `setImmediate` fires, and close handles events such as `socket.on("close")`. `idle`/`prepare` exists but is internal to libuv, so user callbacks never run there.', intro: 'Ask which of these phases would still have work to do in a program that never opens a file or a socket.', tags: ['Node', 'EventLoop'] },
  { q: 'When does a `process.nextTick` callback run?', opts: ['After the timers phase of the current loop iteration', 'Right after the current operation, before the loop continues', 'After every pending promise callback has been run', 'Only when the loop is otherwise idle, as low-priority work'], a: 1, e: '`process.nextTick` callbacks sit in their own queue that Node drains as soon as the current operation finishes — before returning to the event loop and before the promise microtask queue. That is why they beat both timers and `.then` callbacks, and why a `nextTick` that schedules another `nextTick` can starve the loop so that no timer or I/O callback ever runs again.', intro: 'The name is misleading. Ask whether this queue really waits for the next turn of anything.', tags: ['Node', 'EventLoop'] },
  { q: 'When do Promise reaction callbacks (microtasks) run?', opts: ['Before the surrounding synchronous code has finished', 'After the current operation, before macrotasks like timers', 'Only after an I/O callback has completed', 'In the timers phase, alongside setTimeout callbacks'], a: 1, e: 'A promise reaction is queued as a microtask, and the microtask queue drains only once the running synchronous code returns — then it drains completely before Node moves on to the next timer, I/O or `setImmediate` callback. So a `.then` can never interrupt the code around it, but it does run ahead of a `setTimeout(fn, 0)` scheduled at the same moment.', intro: 'Put a `.then` above a `console.log` and run it. Ask whether anything is allowed to interrupt code that is already executing.', tags: ['Node', 'EventLoop'] },
  { q: 'In which phase does `setImmediate` fire?', opts: ['The timers phase', 'The check phase', 'The poll phase', 'The close-callbacks phase'], a: 1, e: '`setImmediate` callbacks run in the check phase, which the loop enters as soon as the poll (I/O) phase finishes. That ordering is why a `setImmediate` scheduled inside an I/O callback runs before a `setTimeout(fn, 0)` scheduled beside it. Timers are their own phase, poll is where I/O callbacks themselves run, and close callbacks handle events such as `socket.on("close")`.', intro: 'Inside an I/O callback it always beats `setTimeout(fn, 0)`. Ask which phase the loop reaches right after it finishes polling.', tags: ['Node', 'EventLoop'] },
  { q: 'Which runs first: `process.nextTick` or a Promise `.then`?', opts: ['The Promise .then', 'process.nextTick', 'Neither — both wait until the next timers phase', 'Whichever was scheduled first'], a: 1, e: 'Node keeps two separate queues and empties the entire `process.nextTick` queue first, then the promise microtask queue, before the loop continues. Scheduling order across the two does not matter: scheduling then1, tick1, then2, tick2 in that source order still runs tick1, tick2, then1, then2. Neither queue waits for the timers phase.', intro: 'Both run before the loop moves on, so this is a question of queue priority, not of scheduling order. Recall which queue Node empties first.', tags: ['Node', 'EventLoop'] },
  { q: 'What happens if you run a long synchronous loop?', opts: ['Other JavaScript keeps running on a second thread', 'It blocks the event loop, stalling timers and I/O', 'Node moves the loop onto a worker thread automatically', 'Only timers are delayed; I/O callbacks still run'], a: 1, e: 'Your JavaScript runs on one thread, so while the loop executes nothing else on that thread can: due timer callbacks, completed I/O callbacks and incoming HTTP requests all wait for it to return. A `setTimeout(fn, 10)` scheduled just before a 300 ms busy loop does not fire until the loop ends, about 300 ms in. libuv\'s thread pool may still finish file or crypto work in the background, but it cannot deliver the callbacks, which is why heavy CPU work belongs in a worker thread or a separate process.', intro: 'There is one thread running your JavaScript. Ask what else is allowed to run on it while your loop is still executing.', tags: ['Node', 'EventLoop'] },
  { q: 'Which library provides Node’s event loop and thread pool?', opts: ['V8', 'libuv', 'OpenSSL', 'zlib'], a: 1, e: 'libuv is the C library behind the event loop, cross-platform async I/O, and the worker thread pool that backs file-system, DNS and some crypto work (its size is set by `UV_THREADPOOL_SIZE`). V8 executes the JavaScript itself, OpenSSL provides TLS and the `crypto` primitives, and zlib provides compression — none of them schedules callbacks. `process.versions` lists all four in a running process.', intro: 'Split Node in two: one bundled dependency executes the JavaScript, another talks to the operating system about files, sockets and timers.', tags: ['Node', 'EventLoop'] },

  // ── Level 6 — Path ─────────────────────────────────────────────────────
  { q: 'What does `path.join("a", "b")` do?', opts: ['Concatenates them into the single string "ab"', 'Joins them with the platform separator and normalizes', 'Resolves them against the cwd into an absolute path', 'Throws unless both segments already exist on disk'], a: 1, e: '`path.join` inserts the platform separator between the segments and normalizes the result, giving `"a/b"` on POSIX and `"a\\b"` on Windows; `join("a", "..", "b", "./c")` collapses to `"b/c"`. It never touches the filesystem, so it cannot throw for a missing file, and it does not make the path absolute — that is `path.resolve`.', intro: 'Node also runs on Windows. Ask what has to go between two segments for the result to be right on both platforms.', tags: ['Node', 'Path'] },
  { q: 'What does `path.resolve` produce?', opts: ['A relative path, with `..` segments preserved', 'An absolute path, built right to left from the cwd', 'A file URL string beginning with `file://`', 'The same string, with separators normalized'], a: 1, e: '`path.resolve` always returns an absolute path. It walks the segments right to left and stops at the first absolute one — `path.resolve("/x", "y", "/z", "w")` is `"/z/w"` — and if none is absolute it prepends the current working directory. Merely combining and normalizing is `path.join`, which leaves `path.join("a", "b")` relative; converting to a `file://` URL is `pathToFileURL`.', intro: 'Ask what it has to fall back on when every segment you hand it is relative.', tags: ['Node', 'Path'] },
  { q: 'What is `path.basename("/a/b.txt")`?', opts: ['"/a"', '"b.txt"', '".txt"', '"b"'], a: 1, e: '`path.basename` returns the last segment, extension included: `"b.txt"`. The other three are what its siblings return for the same input — `path.dirname` gives `"/a"`, `path.extname` gives `".txt"`, and `path.basename("/a/b.txt", ".txt")` gives `"b"` when you pass the extension you want stripped.', intro: 'Every option here is what some `path` function returns for this exact input. Decide which part of the path the word "base" names.', tags: ['Node', 'Path'] },
  { q: 'What is `path.extname("index.html")`?', opts: ['"index"', '"html"', '".html"', '""'], a: 2, e: '`path.extname` includes the leading dot, so `"index.html"` gives `".html"` and the comparison must be written `extname(p) === ".html"`, not `"html"`. It reads from the last dot only, so `"a.tar.gz"` gives `".gz"`, and a name with no dot at all gives `""` — which is what the empty-string option describes.', intro: 'You are about to compare the result against a literal in an `if`. Recall the exact string Node hands back, character for character.', tags: ['Node', 'Path'] },
  { q: 'What is `path.dirname("/a/b/c.js")`?', opts: ['"c.js"', '"/a/b"', '"/a"', '"/a/b/c.js"'], a: 1, e: '`path.dirname` drops exactly the last segment and returns the directory holding it: `"/a/b"`. `"c.js"` is what `path.basename` returns, `"/a"` drops one segment too many, and the unchanged string is what you get if nothing is removed. Together, `dirname` and `basename` split any path into directory and file name.', intro: 'Decide how many segments the function drops from the end of the path — one, or all but one.', tags: ['Node', 'Path'] },
  { q: 'Which approach builds a nested path correctly on both Windows and POSIX systems?', opts: ['Concatenate the segments with a hard-coded backslash', 'Call path.join("logs", "today.txt")', 'Concatenate the segments, then call path.normalize on the result', 'Append path.sep to the end of the finished path'], a: 1, e: '`path.join` inserts whatever separator the platform uses and normalizes the result: `"logs/today.txt"` on POSIX, `"logs\\today.txt"` on Windows. A hard-coded backslash breaks on POSIX, `path.normalize` cannot restore a separator that was never written (`"logs" + "today.txt"` is just `"logstoday.txt"`), and appending `path.sep` at the end leaves a trailing separator instead of joining anything.', intro: 'Run the same line on Windows and on Linux. Ask which option produces a different — and correct — string on each.', tags: ['Node', 'Path'] },
  { q: 'What does `path.parse(p)` return?', opts: ['An array of the path\'s segments, in order', 'An object with root, dir, base, ext and name', 'A normalized copy of the path as a string', 'A Buffer holding the path\'s raw bytes'], a: 1, e: '`path.parse("/a/b/c.txt")` returns `{ root: "/", dir: "/a/b", base: "c.txt", ext: ".txt", name: "c" }`, so one call replaces separate `dirname`, `basename` and `extname` calls. `path.format` converts such an object back into a string, which makes "change the extension" a two-line rename. No `path` function returns a Buffer or an array of segments.', intro: 'You want the directory, the file name and the extension from a single call. Ask what shape can carry all three at once.', tags: ['Node', 'Path'] },
  { q: 'How does `path.resolve` differ from `path.join`?', opts: ['They differ only in the separator each one inserts', 'resolve yields an absolute path; join just combines segments', 'join is absolute; resolve is relative', 'join checks that the path exists; resolve does not'], a: 1, e: '`path.join` concatenates and normalizes, and its result is absolute only if a segment already was — `join("a", "b")` is `"a/b"`. `path.resolve` guarantees an absolute path: it walks the segments right to left, stops at the first absolute one, and prepends the current working directory if it never finds one, so `resolve("a", "b")` is `"<cwd>/a/b"`. Neither inspects the filesystem, and neither uses a different separator from the other.', intro: 'Both take segments and hand back a string. The difference is what each one guarantees about the start of that string.', tags: ['Node', 'Path'] },

  // ── Level 7 — File System ──────────────────────────────────────────────
  { q: 'Which module reads and writes files?', opts: ['os', 'fs', 'path', 'net'], a: 1, e: '`fs` is the file-system module: `readFile`, `writeFile`, `readdir`, `stat` and their `Sync` and promise variants all live there. `path` only manipulates path strings and never opens anything, `os` reports on the machine (platform, CPUs, memory, tmpdir), and `net` provides TCP sockets rather than files.', intro: 'These names are abbreviations. Expand all four and one of them will name the thing that stores files.', tags: ['Node', 'fs'] },
  { q: 'How does `fs.readFileSync` behave?', opts: ['Asynchronously', 'Synchronously, blocking until done', 'It streams', 'It returns a Promise'], a: 1, e: '`fs.readFileSync` blocks the thread until the whole file is read, then returns the data directly — a Buffer, or a string if you pass an encoding. Nothing else runs meanwhile: a `setImmediate` queued before the call still does not fire during it. The other options are separate APIs — `fs.readFile` takes a callback, `fs.promises.readFile` returns a promise, `fs.createReadStream` streams — so a Sync call is fine at startup but not inside a request handler.', intro: 'Ask what the event loop manages to get done between the call and the moment it returns a value.', tags: ['Node', 'fs'] },
  { q: 'What does `fs.promises.readFile` return?', opts: ['The file contents right away, as a Buffer', 'A Promise that resolves to the file contents', 'Nothing; the contents arrive through a callback', 'A Readable stream of the file'], a: 1, e: 'fs.promises.readFile starts the read and immediately returns a Promise that later resolves to the contents (a Buffer, or a string when you pass an encoding), so you await it or chain .then(). Getting a Buffer right away would require blocking, which is what fs.readFileSync does; a callback is the shape of fs.readFile; a stream comes from fs.createReadStream, not from readFile.', intro: 'The call cannot block and there is no callback parameter here. Where does an asynchronous result have to go?', tags: ['Node', 'fs'] },
  { q: 'How do you read a file as text instead of a Buffer?', opts: ['Pass an encoding such as "utf8" to the read call', 'Call fs.readText instead of fs.readFile', 'Read it with fs.readFileSync, which always returns a string', 'Set process.env.LANG to a UTF-8 locale before reading'], a: 0, e: 'Every fs read (readFile, readFileSync, fs.promises.readFile) accepts an encoding, either as a string or as { encoding: "utf8" }; with one set, fs decodes the bytes and returns a string, without it you get a Buffer. There is no fs.readText, readFileSync returns a Buffer just like the async variants unless given an encoding, and the process locale does not change what fs returns.', intro: 'There is no separate text-reading function in fs; the same call returns a Buffer or a string depending on what you tell it.', tags: ['Node', 'fs'] },
  { q: 'What does `fs.writeFile` do when the file already exists?', opts: ['Appends the new data after the existing contents', 'Replaces the existing contents with the new data', 'Rejects with EEXIST so nothing is lost', 'Writes to a temporary file and keeps the original'], a: 1, e: 'writeFile opens the path with flag "w", which truncates an existing file to zero length before writing, so the old contents are replaced; a missing file is created. Appending needs fs.appendFile or flag "a", and if you want the call to refuse an existing file use flag "wx", which fails with EEXIST. Nothing is written to a temporary file for you.', intro: 'Think about the default open flag writeFile uses and what that flag does to a file that is already there.', tags: ['Node', 'fs'] },
  { q: 'What does `fs.appendFile` do?', opts: ['Replaces whatever the file held with the data', 'Adds the data after the file\'s current contents', 'Inserts the data before the file\'s current contents', 'Fails with ENOENT unless the file already exists'], a: 1, e: 'appendFile opens the path with flag "a", so every write lands after the existing contents and the file is created when it is missing. writeFile is the call that replaces contents, fs has no prepend mode, and appendFile does not require the file to exist first.', intro: 'Contrast it with writeFile, and remember that both calls create the file when it does not exist yet.', tags: ['Node', 'fs'] },
  { q: 'What does `fs.mkdir(dir, { recursive: true })` do?', opts: ['Fails with ENOENT when a parent directory is missing', 'Creates the directory and any missing parent directories', 'Creates the directory only if its parent already exists', 'Throws EEXIST when the directory already exists'], a: 1, e: 'With recursive: true, mkdir behaves like mkdir -p: it creates each missing parent in turn and succeeds silently when the directory already exists (returning the first path it created, or undefined if nothing was created). Without the option a missing parent fails with ENOENT and an existing target fails with EEXIST.', intro: 'Think of mkdir -p on the command line and what the -p flag saves you from doing by hand.', tags: ['Node', 'fs'] },
  { q: 'What does `fs.existsSync(p)` return?', opts: ['The file\'s contents as a Buffer', 'true or false, depending on whether the path exists', 'The file\'s size in bytes, or -1 when it is missing', 'A Promise that resolves once the path exists'], a: 1, e: 'existsSync stats the path synchronously and returns true or false; it never returns contents or size and, unlike the fs.promises API, involves no Promise. Checking first and acting later leaves a window in which the file can change, so for reads it is usually better to attempt the operation and handle ENOENT.', intro: 'The Sync suffix means the result comes back directly rather than through a Promise; then think about what kind of value an "exists" check produces.', tags: ['Node', 'fs'] },

  // ── Level 8 — OS & Util ────────────────────────────────────────────────
  { q: 'What does `os.platform()` return?', opts: ['The Node.js version, e.g. "v22.12.0"', 'The platform identifier, e.g. "linux" or "win32"', 'The logical CPU count, e.g. 8', 'The machine\'s host name, e.g. "web-01"'], a: 1, e: 'os.platform() returns the same string as process.platform: "linux", "darwin", "win32" and so on, which is what you branch on for platform-specific behaviour. The Node version is process.version, a CPU count comes from os.availableParallelism() (or os.cpus().length), and the host name from os.hostname().', intro: 'Think of the value you would branch on to run Windows-specific code.', tags: ['Node', 'os'] },
  { q: 'What does `os.cpus()` return?', opts: ['The total system memory in bytes', 'An array with one object per logical CPU core', 'A single number: the count of CPU cores', 'The 1-, 5- and 15-minute load averages'], a: 1, e: 'os.cpus() returns an array whose entries describe each logical core: model, speed in MHz and a times object with user/nice/sys/idle/irq milliseconds. It is not a bare count; when you only need how many workers to start, os.availableParallelism() is the recommended call. Memory comes from os.totalmem()/os.freemem() and load averages from os.loadavg().', intro: 'Read the name as a plural rather than a count, and ask what the OS can tell you about one core.', tags: ['Node', 'os'] },
  { q: 'What does `os.totalmem()` return?', opts: ['Free space on the root disk, in bytes', 'Total installed system memory, in bytes', 'The percentage of memory currently in use', 'The memory page size, in bytes'], a: 1, e: 'os.totalmem() returns the total physical memory as an integer number of bytes (divide by 1024 ** 3 for GiB); os.freemem() gives the free amount and the process\'s own usage comes from process.memoryUsage(). Disk space is not part of the os module, and Node reports no percentage: you compute it from totalmem and freemem yourself.', intro: 'Two things to settle: which resource "mem" refers to, and the unit Node uses for every memory figure it reports.', tags: ['Node', 'os'] },
  { q: 'What does `os.homedir()` return?', opts: ['The system temporary directory, e.g. /tmp', 'The current user\'s home directory, e.g. /home/ana', 'The process\'s current working directory', 'The filesystem root, e.g. / or C:\\'], a: 1, e: 'os.homedir() returns the home directory of the user running the process (on POSIX it honours $HOME when set), which is where per-user config such as ~/.npmrc belongs. The temporary directory is os.tmpdir(), the working directory is process.cwd(), and the root can be read from path.parse(process.cwd()).root.', intro: 'Think of where a CLI tool keeps a per-user config file such as ~/.npmrc, and which folder that tilde expands to.', tags: ['Node', 'os'] },
  { q: 'What does `util.promisify(fn)` do?', opts: ['Caches fn\'s results so repeated calls with the same arguments skip the work', 'Wraps fn so it returns a Promise instead of taking an error-first callback', 'Runs fn on a worker thread so it no longer blocks the event loop', 'Marks fn as async so its return value is wrapped in a resolved Promise'], a: 1, e: 'util.promisify(fn) returns a new function that calls fn with a generated (err, value) callback and returns a Promise: it rejects with err or resolves with value. Nothing is cached and no thread is involved, and the return value of fn is ignored, so a plain synchronous function never calls the callback and the Promise never settles.', intro: 'Consider what fn expects as its last argument, and what modern async code would rather receive instead.', tags: ['Node', 'util'] },
  { q: 'Log lines collected from several servers must show which machine wrote each one. Which call returns that machine\'s name?', opts: ['os.networkInterfaces()', 'os.hostname()', 'os.userInfo()', 'os.release()'], a: 1, e: 'os.hostname() returns the host name the operating system reports for the machine, e.g. "web-01", which is stable per machine and readable in a log line. os.release() describes the kernel or OS build ("6.8.0-45-generic"), os.userInfo() the account running the process, and os.networkInterfaces() a map of adapters and addresses; none of them names the machine.', intro: 'Ask what each call identifies: the OS build, the network adapters, the user account, or the machine itself.', tags: ['Node', 'os'] },
  { q: 'What is `util.inspect(obj)` useful for?', opts: ['Releasing the memory an object occupies', 'Producing a readable string form of a value', 'Validating a value against a type schema', 'Creating a deep copy of a nested object'], a: 1, e: 'util.inspect(value, options) returns a string that shows nested objects, arrays, Maps and class names in a readable layout (options such as depth control how much); console.log uses the same machinery through util.format for non-string arguments, and classes can customise it with [util.inspect.custom]. It never mutates or frees anything, does no validation, and deep copies come from structuredClone().', intro: 'console.log does not render a nested object by magic; it delegates to a util helper first. What would that helper have to hand back?', tags: ['Node', 'util'] },
  { q: 'A generated local text file should use the host platform’s native line ending. Which expression fits?', opts: ['lines.join("")', 'lines.join(os.EOL)', 'lines.join(path.sep)', 'lines.join(process.platform)'], a: 1, e: 'os.EOL is the string the current platform uses to end a line: "\\n" on POSIX and "\\r\\n" on Windows, so lines.join(os.EOL) writes native line endings. path.sep is the path-segment separator ("/" or "\\\\"), process.platform is a name like "linux", and joining with "" produces no line breaks at all. When the file is meant for git or cross-platform tooling rather than a local editor, a fixed "\\n" is often the better choice.', intro: 'Windows and POSIX end lines differently; look for the constant Node sets to the current platform\'s line terminator.', tags: ['Node', 'os'] },

  // ── Level 9 — Events ───────────────────────────────────────────────────
  { q: 'What does `emitter.on("evt", fn)` do?', opts: ['Emits the event', 'Registers fn as a listener for "evt"', 'Removes a listener', 'Runs fn once and removes it'], a: 1, e: '.on() subscribes fn to "evt": every later emit("evt", …) calls it, in registration order, with the emit arguments. emit() is the producing side, .off()/removeListener() unsubscribes, and .once() is the variant that removes the listener after its first call.', intro: 'Decide whether this call produces events or reacts to them, and whether that reaction is permanent.', tags: ['Node', 'Events'] },
  { q: 'What does `emitter.emit("evt", data)` do?', opts: ['Schedules the event for later', 'Synchronously calls all listeners for "evt"', 'Removes listeners', 'Returns a Promise'], a: 1, e: 'emit() calls each listener registered for "evt" immediately and in registration order, passing data along, and only then returns a boolean (true if there was at least one listener). Nothing is queued for a later tick and no Promise is involved; if a listener throws, the exception surfaces from the emit() call itself. To defer work, the listener has to use setImmediate or a Promise.', intro: 'Put a console.log right after the emit call and ask whether the listeners\' output can appear before or after it.', tags: ['Node', 'Events'] },
  { q: 'How does `emitter.once` differ from `.on`?', opts: ['The listener runs only while no other listener is registered', 'The listener runs at most once and is then removed', 'The listener runs before any listener added with .on', 'The listener runs asynchronously on the next event-loop turn'], a: 1, e: '.once() wraps the listener so that the first matching emit calls it and unregisters it; later emits do nothing. Otherwise it is a normal listener: it runs synchronously and in registration order alongside .on() listeners (prependOnceListener exists for ordering), and its presence does not depend on other listeners. The promise-based events.once(emitter, name) is the same idea for await.', intro: 'The name states a quantity. Ask what the emitter must do to the listener after that quantity is reached.', tags: ['Node', 'Events'] },
  { q: 'Which call removes one specific listener that was added earlier with .on?', opts: ['emitter.stop("evt", fn)', 'emitter.off("evt", fn)', 'emitter.delete("evt", fn)', 'emitter.clear("evt", fn)'], a: 1, e: 'emitter.off("evt", fn), an alias of removeListener, detaches that exact function from that event; the emitter compares references, so an anonymous inline listener cannot be removed later. removeAllListeners("evt") drops every listener at once; stop, delete and clear do not exist on EventEmitter. Removing listeners when a component or connection goes away prevents leaks and the MaxListenersExceeded warning.', intro: 'You must pass the same function reference you registered; the emitter can only detach what it can match. Recall which method pairs with .on for that.', tags: ['Node', 'Events'] },
  { q: 'What is special about the "error" event on an EventEmitter?', opts: ['It is silently dropped when nobody listens', 'It is thrown when nobody listens, crashing the process', 'It is retried automatically on the next tick', 'It pauses the event loop until a listener appears'], a: 1, e: 'EventEmitter treats "error" as a special case: emit("error", err) with no registered listener rethrows the error, so an unhandled socket or stream failure ends the process. Every other event name is simply dropped when nobody listens, which is what makes "silently dropped" so tempting here. Nothing is retried and the loop is not paused, so attach an "error" listener to every emitter you keep alive.', intro: 'One event name is treated differently when nobody is listening. Ask what happens to the Error object that was emitted if no handler takes it.', tags: ['Node', 'Events'] },
  { q: 'Which of these Node objects inherit from EventEmitter?', opts: ['Buffers and the objects returned by JSON.parse', 'Streams, HTTP servers and network sockets', 'Only the timer handles returned by setTimeout', 'Only the promises returned by fs.promises'], a: 1, e: 'Streams, http.Server and net.Socket all extend EventEmitter, which is why you write server.on("request", ...) or stream.on("data", ...). A Buffer is a fixed byte array, a timer handle is a scheduling record and a promise settles exactly once, so none of them need on/emit. Knowing the base class tells you an object has .on, .once and .off, and that it obeys the unhandled-"error" rule.', intro: 'Emitters are the objects that report things happening over time. Ask which of these has anything to announce after you get hold of it.', tags: ['Node', 'Events'] },
  { q: 'What does `emitter.listenerCount("evt")` return?', opts: ['The data from the last emit of that event', 'How many listeners are registered for that event', 'true when at least one listener is registered', 'The value the last listener returned'], a: 1, e: 'listenerCount("evt") returns a number: the listeners currently registered for that event, including ones added with once. It is not a boolean and not event data — emit passes the arguments to listeners and returns true/false, and listener return values are discarded. Logging the count around setup and teardown is the quickest way to confirm a suspected leak before the MaxListenersExceededWarning shows up.', intro: 'You suspect handlers are piling up on one event. Ask what you would log before and after teardown to see it.', tags: ['Node', 'Events'] },
  { q: 'An EventEmitter warns after code repeatedly adds listeners for the same event. What should you investigate first?', opts: ['Whether emit removes listeners after it has called them', 'Whether setup runs more than once without matching cleanup', 'Whether the listener is async and returns a promise', 'Whether the default limit of ten is simply too low here'], a: 1, e: 'Node warns once more than ten listeners are attached to a single event on a single emitter, because that usually means a subscribe path — a request handler, a reconnect, a re-mount — runs again without a matching off/removeListener. `emit` does not remove the listeners it calls, apart from `once` listeners that remove themselves, and an async listener does not affect the count. Raising the ceiling with setMaxListeners is reasonable only after you have confirmed every listener is genuinely needed; used first, it hides the leak.', intro: 'Ten is a diagnostic threshold, not a hard limit. Ask what the count is telling you about the code that registered them.', tags: ['Node', 'Events'] },

  // ── Level 10 — Streams ─────────────────────────────────────────────────
  { q: 'A request handler has to send a 2 GB file. What does fs.createReadStream give you that fs.readFile does not?', opts: ['It reads the file without any system calls', 'It delivers the file in chunks, so memory stays bounded', 'It reads the file synchronously, so ordering is simpler', 'It skips the event loop, so the response is faster'], a: 1, e: 'createReadStream emits the file in chunks — 64 KiB by default — so the process holds one chunk at a time and can start writing the response before the read finishes. readFile keeps the whole file in memory before your callback runs; with a utf8 encoding it cannot even build the string, since a JavaScript string tops out near 512 MB. Streams are still asynchronous and still run on the event loop: the gain is bounded memory and an earlier first byte, not bypassing either.', intro: 'Both APIs are asynchronous and both run on the event loop. Ask what else could differ when the file is 2 GB.', tags: ['Node', 'Streams'] },
  { q: 'What are the four fundamental stream types?', opts: ['Open, Close, Read, Write', 'Readable, Writable, Duplex, Transform', 'In, Out, Pipe, Buffer', 'Sync, Async, File, Net'], a: 1, e: 'Node defines four: Readable (fs.createReadStream), Writable (fs.createWriteStream), Duplex — readable and writable at once, like net.Socket — and Transform, a Duplex whose output is computed from its input, like zlib.createGzip. The other lists mix up events (open, close), operations (pipe) and modules (file, net), none of which are stream classes. You need the taxonomy the moment you implement a stream yourself and have to pick a base class.', intro: 'Think of four concrete objects: a file reader, a file writer, a TCP socket, and a gzip stream. Each one names a type.', tags: ['Node', 'Streams'] },
  { q: 'What does a readable stream’s "data" event provide?', opts: ['The whole file contents in one value', 'One chunk of the data as it arrives', 'The number of bytes read so far', 'The final result after the stream ends'], a: 1, e: 'Each "data" event carries one chunk — a Buffer by default, or a string if you set an encoding — and fires again and again until "end". Nothing hands you the whole file: if you need it whole, you collect the chunks and Buffer.concat them at the end. Turning individual Buffer chunks into strings yourself can split a multi-byte character across a chunk boundary, which is why the encoding option and StringDecoder exist.', intro: 'The handler runs many times for one file. Ask what a single call can hand you at the moment it runs.', tags: ['Node', 'Streams'] },
  { q: 'What does `readable.pipe(writable)` do?', opts: ['Copies the data synchronously and returns when it is done', 'Forwards data from the readable into the writable', 'Closes both streams as soon as they are connected', 'Reads the writable back into the readable'], a: 1, e: 'pipe() subscribes to the readable and writes every chunk into the writable, pausing the source whenever the destination\'s buffer is full, so a slow disk or socket cannot grow memory without limit. It returns the destination, which is what lets you chain a Transform in the middle. One caveat worth knowing: if the source errors, pipe does not destroy the destination, so use stream.pipeline() when failures have to be cleaned up.', intro: 'Two streams, one direction. Ask what happens to each chunk, and who has to wait when the destination cannot keep up.', tags: ['Node', 'Streams'] },
  { q: 'What does `fs.createReadStream("f")` return?', opts: ['The file contents', 'A Readable stream of the file', 'A Promise', 'A Buffer'], a: 1, e: 'createReadStream returns an fs.ReadStream — a Readable — right away, and the bytes arrive later through "data"/"end" or through pipe. It is not a promise: there is no .then, and the promise-based file API is fs.promises.readFile, which resolves to the whole content instead. It is not a Buffer either; each chunk you receive is one. Reach for it when the file is large or when you want to start responding before the read finishes.', intro: 'The call returns before a single byte has been read. Ask what kind of object it can hand back at that point.', tags: ['Node', 'Streams'] },
  { q: 'What is "backpressure"?', opts: ['A network error raised when a socket is busy', 'Slowing the producer when the consumer cannot keep up', 'Reversing the direction of data through a pipe', 'Compressing data so that less of it has to be written'], a: 1, e: 'Backpressure is flow control: once a writable\'s buffered bytes pass its highWaterMark, write() returns false and the producer is expected to stop until the "drain" event — which is exactly what pipe() does on your behalf. It is not an error and not compression; the data is fine, it is just queued. Ignoring the false return is how a fast reader and a slow socket turn into unbounded memory growth.', intro: 'Nothing here is broken and nothing gets smaller. Ask what a full buffer at the destination changes for whoever is writing.', tags: ['Node', 'Streams'] },
  { q: 'What does a Transform stream do?', opts: ['It reads input only, like a file reader', 'It reads input, changes it, and emits the changed output', 'It writes output only, like a file writer', 'It buffers all input and writes it once the stream closes'], a: 1, e: 'A Transform is a Duplex — writable on one side, readable on the other — whose output is produced from what you write in, chunk by chunk: zlib.createGzip, a crypto Cipher, a CSV parser. Readable-only and Writable-only streams move bytes in one direction without changing them. Nothing about a Transform requires holding the whole input, which is exactly why one can sit in the middle of a pipeline over a huge file.', intro: 'Ask which of these could sit in the middle of a pipe, with another stream on each side of it.', tags: ['Node', 'Streams'] },
  { q: 'What does the "end" event on a readable mean?', opts: ['An error occurred', 'There is no more data to read', 'The stream paused', 'A new chunk arrived'], a: 1, e: '"end" fires once, after the last chunk has been handed to a consumer: no more data is coming, so this is where you assemble the final result. It is not an error and not a pause — and it only arrives if something is actually consuming the stream, so a readable left paused with no "data" listener and no pipe never ends. On a writable the matching event is "finish", not "end".', intro: 'It is the counterpart of the repeated "data" event. Ask what has to have happened to every chunk before it can fire.', tags: ['Node', 'Streams'] },

  // ── Level 11 — Buffers ─────────────────────────────────────────────────
  { q: 'What does a Buffer represent?', opts: ['A string only', 'A fixed-length chunk of raw binary data', 'A JSON object', 'A stream'], a: 1, e: 'A Buffer is a fixed-length sequence of bytes and a subclass of Uint8Array, used wherever Node deals in raw binary: fs.readFile without an encoding, socket payloads, crypto digests. It is not text — a string only appears when you decode with an encoding — and the length never changes, so writing past the end is silently ignored rather than growing the buffer. A stream is the transport that delivers Buffers; the Buffer is the container.', intro: 'Ask what `fs.readFile` hands your callback when you do not pass an encoding.', tags: ['Node', 'Buffers'] },
  { q: 'What does `Buffer.from("hi")` create?', opts: ['A string', 'A Buffer holding those bytes', 'An array of chars', 'A Promise'], a: 1, e: 'Buffer.from("hi") encodes the string as bytes — UTF-8 unless you pass another encoding — producing the two-byte <Buffer 68 69>. The result is a Buffer object, not a string and not an array of characters, and the call is synchronous, so nothing here is a promise. Because it stores bytes, its length is the byte length: "héllo" is five characters but a six-byte Buffer.', intro: 'The argument is text, the result is not. Ask what those two characters look like once they are stored the way a Buffer stores things.', tags: ['Node', 'Buffers'] },
  { q: 'What does `buf.toString("utf8")` do?', opts: ['Returns the buffer\'s length in bytes', 'Decodes the bytes into a UTF-8 string', 'Replaces the buffer\'s contents with text', 'Encodes the bytes as base64 text'], a: 1, e: 'toString(encoding) reads the bytes and builds a string in that encoding, leaving the Buffer itself untouched; Buffer.from is the opposite direction. The encoding argument decides the output, so "base64" or "hex" would give those representations instead — with "utf8" you get the decoded text. The byte count is buf.length, and it is the same before and after any toString call.', intro: 'The argument names an encoding. Ask which direction the conversion runs, and what would change if you passed "base64" instead.', tags: ['Node', 'Buffers'] },
  { q: 'Which of these calls hands you a Buffer?', opts: ['fs.readFile(path, "utf8")', 'crypto.createHash("sha256").update(data).digest()', 'JSON.parse(text)', 'res.setHeader("Content-Type", "application/json")'], a: 1, e: 'digest() returns the 32 raw bytes of the hash as a Buffer; you choose a representation afterwards with digest("hex") or buf.toString("base64"). readFile with an encoding decodes for you and gives a string — drop the encoding and it gives a Buffer instead — while JSON.parse produces JavaScript values and setHeader hands back the response object for chaining. Buffers show up wherever bytes are the truth: file and socket I/O, crypto, images, binary protocols.', intro: 'Ask which result has no natural text form until you pick an encoding for it yourself.', tags: ['Node', 'Buffers'] },
  { q: 'What does `Buffer.alloc(10)` produce?', opts: ['A string of ten zero characters', 'A ten-byte buffer filled with zeros', 'An empty buffer that grows as you write', 'Ten separate one-byte buffers'], a: 1, e: 'Buffer.alloc(10) reserves ten bytes and zero-fills them, so the contents are defined before you write anything: <Buffer 00 00 00 00 00 00 00 00 00 00>. The length is fixed at ten — a Buffer never grows, and a write past the end is ignored — and a second argument sets a different fill, as in Buffer.alloc(4, 1). Zero-filling is precisely what separates alloc from Buffer.allocUnsafe.', intro: 'The number is a size in bytes, and alloc promises a known starting state. Ask what that state is.', tags: ['Node', 'Buffers'] },
  { q: 'What is the default encoding for `buf.toString()`?', opts: ['ascii', 'utf8', 'hex', 'base64'], a: 1, e: 'Both directions default to UTF-8: buf.toString() decodes as UTF-8 and Buffer.from(str) encodes as UTF-8. The difference matters for the near miss — "ascii" mangles every byte above 0x7F, so the UTF-8 bytes of é (c3 a9) come back as two wrong characters instead of one. "hex" and "base64" are representations you have to ask for, normally when bytes need to travel as text.', intro: 'Node applies the same default whenever an encoding is left out, in Buffer.from as well as toString. Recall which text encoding that is.', tags: ['Node', 'Buffers'] },
  { q: 'What does this evaluate to?\n\n```js\nBuffer.from("héllo", "utf8").length;\n```', opts: ['5, one per character', '6, because é takes two bytes in UTF-8', '10, two bytes per character', '11, the characters plus a terminator'], a: 1, e: 'buf.length counts bytes, not characters: "héllo" is five JavaScript characters, but UTF-8 encodes é as the two bytes c3 a9, so the Buffer holds six. Counting characters gives 5; 10 would be UTF-16, where each of these characters takes two bytes; nothing appends a terminator. This is why Buffer.byteLength(str) rather than str.length is the right value for a Content-Length header.', intro: 'buf.length is a count of stored units. Settle which unit a Buffer stores before you count anything on screen.', tags: ['Node', 'Buffers'] },
  { q: 'How does `Buffer.allocUnsafe` differ from `Buffer.alloc`?', opts: ['It is slower, because it validates every byte', 'It skips zero-filling, so the memory may hold old data', 'It throws if the buffer is written to later', 'It allocates a buffer whose length can grow'], a: 1, e: 'allocUnsafe hands back memory without clearing it, so the bytes are whatever was there before — possibly fragments of an earlier request — which is why it is faster and why you must overwrite every byte before anything else sees the buffer. alloc zero-fills first: slower, but a defined starting state. Neither call refuses later writes and neither buffer can grow, so the only real trade-off is speed against leftover contents.', intro: 'Recall what `Buffer.alloc` guarantees about its bytes before you write, then ask what a faster call trades away.', tags: ['Node', 'Buffers'] },

  // ── Level 12 — HTTP Server ─────────────────────────────────────────────
  { q: 'Which core module creates a basic HTTP server?', opts: ['net', 'http', 'url', 'dns'], a: 1, e: 'http.createServer() returns a server that parses incoming requests and calls your handler with (req, res). net is the near miss: it creates TCP servers, but a net socket hands you raw bytes — you would receive the literal line "GET /hello HTTP/1.1" and have to parse the request yourself. url only parses URL strings and dns resolves names; neither creates a server at all.', intro: 'All four are real core modules. Ask which one understands requests, status codes and headers rather than raw bytes or names.', tags: ['Node', 'HTTP'] },
  { q: 'What arguments does the `http.createServer` callback receive?', opts: ['(err, data)', '(req, res)', '(socket)', '(next)'], a: 1, e: 'The request listener is called with (req, res): an http.IncomingMessage carrying method, url and headers, and an http.ServerResponse you write the answer into. It is deliberately not error-first — a failed request is not an error argument here, it is a status code you send back. (socket) is what net.createServer gives you, and (next) belongs to Express middleware, which adds that third argument on top of req and res.', intro: 'Node\'s other callbacks put an error first. Ask whether a request that fails is an error for the server answering it.', tags: ['Node', 'HTTP'] },
  { q: 'What does `res.writeHead(200, headers)` set?', opts: ['The body', 'The status code and response headers', 'The URL', 'The method'], a: 1, e: 'writeHead sends the status line and the response headers, so immediately afterwards res.headersSent is true and no header can be changed — which is why it has to come before res.write or res.end. The URL and the method belong to the request (req.url, req.method), not the response, and the body is whatever you pass to write/end next. Use res.setHeader instead when you want to build headers up one call at a time.', intro: 'It runs before anything is written to the body. Ask which parts of an HTTP response have to be decided first.', tags: ['Node', 'HTTP'] },
  { q: 'What does `res.end()` do?', opts: ['Starts the server', 'Finishes the response (optionally sending data)', 'Closes the port', 'Throws'], a: 1, e: 'res.end() finishes that one response — you may pass a last chunk to send with it — and the client can stop waiting; the server keeps listening and the port stays open for the next request. Forget it and the request hangs until a timeout kills it; write after it and the response stream errors with ERR_STREAM_WRITE_AFTER_END. Ending a response has nothing to do with starting or stopping the server itself.', intro: 'One server, many requests, one response at a time. Ask what has to happen before this client stops waiting.', tags: ['Node', 'HTTP'] },
  { q: 'What does `server.listen(3000)` do?', opts: ['Sends a request', 'Binds the server to port 3000', 'Stops the server', 'Reads a file'], a: 1, e: 'listen(3000) asks the OS to bind port 3000 and begin accepting connections. Binding is asynchronous: server.listening is still false on the next line, and the "listening" event or the callback is what tells you the port is really yours — if another process holds it, EADDRINUSE surfaces here, not at createServer. Sending a request is the client side (http.request), and server.close() is the reverse of listen.', intro: 'Nothing can reach the server before this call. Ask what a server has to obtain from the operating system first.', tags: ['Node', 'HTTP'] },
  { q: 'What does `req.url` contain inside an http server handler?', opts: ['The full URL, including scheme and host', 'The path and query string of the request', 'The status code the response will use', 'The client\'s IP address'], a: 1, e: 'req.url is the request target exactly as it appears on the request line — the path plus any query string, e.g. "/users/42?sort=asc" — with no scheme and no host, because the host travels separately in req.headers.host. When you need an absolute URL, combine them: new URL(req.url, `http://${req.headers.host}`). The status code belongs to the response, and the client address is req.socket.remoteAddress.', intro: 'The client sent a request line and a Host header separately. Ask which of the two the request line carries.', tags: ['Node', 'HTTP'] },
  { q: 'What does `req.method` contain?', opts: ['The body', 'The HTTP method (GET, POST, …)', 'The headers', 'The URL'], a: 1, e: 'req.method is the HTTP verb as an uppercase string — "GET", "POST", "DELETE" — and it is what a router branches on first. The other three live elsewhere: req.headers holds the headers, req.url the path and query, and the body is not a property at all, since req is a readable stream you have to consume. Checking the method is also how you reject a write that arrives as a GET.', intro: 'A handler usually branches on this before it does anything else. Ask which part of the request line it carries.', tags: ['Node', 'HTTP'] },
  { q: 'To return JSON, which response header should you set?', opts: ['Content-Type: text/html', 'Content-Type: application/json', 'Accept: json', 'Encoding: json'], a: 1, e: 'Content-Type: application/json on the response tells the client how to read the body, so browsers and fetch clients parse it as JSON instead of rendering or downloading it. Accept is a request header — what the client would like to receive, not what you are sending — and there is no "Encoding: json" header at all. Sending text/html for a JSON body is the common bug: the bytes still arrive, but any client that trusts the type handles them wrongly.', intro: 'One header describes what you are sending; another describes what the other side is willing to take. Which direction does a response speak in?', tags: ['Node', 'HTTP'] },

  // ── Level 13 — Callbacks & Promisify ───────────────────────────────────
  { q: 'What is Node’s conventional callback signature?', opts: ['(data, err)', '(err, data)', '(result)', '(success, fail)'], a: 1, e: 'Node\'s convention is error-first: cb(err, result), where err is null when the call succeeded. Putting the error in first position means you cannot reach the result without stepping past it, which is what keeps the failure path visible; the reversed (data, err) shape is exactly how errors get read as data and dropped. The bridge to promises depends on this shape: util.promisify wraps any function that follows it, treating the first callback argument as the failure and the second as the value.', intro: 'The convention exists so that one particular argument cannot be skipped by accident. Ask which argument that has to be.', tags: ['Node', 'Callbacks'] },
  { q: 'Why does Node use error-first callbacks?', opts: ['To make code shorter', 'So errors are surfaced and handled explicitly', 'To improve speed', 'To avoid Promises'], a: 1, e: 'Putting the error first makes it a consistent, hard-to-ignore part of every async call.', tags: ['Node', 'Callbacks'] },
  { q: 'What is "callback hell"?', opts: ['A runtime error thrown by nested callbacks', 'Deeply nested callbacks that are hard to read', 'A callback that is never called', 'A callback that is called more than once'], a: 1, e: 'Callback hell is the pyramid you get when every asynchronous step starts inside the previous callback: the code drifts right, error handling is repeated at each level, and the order of operations is hard to follow. It is a readability and maintenance problem, not a runtime failure — the program still works, unlike a callback that is never called or one called twice. Promises and async/await flatten the same sequence into ordinary statements, which is why new Node code rarely nests callbacks.', intro: 'Picture five file operations where each one needs the result of the one before. Ask what shape that code takes on screen.', tags: ['Node', 'Callbacks'] },
  { q: 'What kind of function can `util.promisify` wrap?', opts: ['Any function', 'One that uses the error-first callback convention', 'Only synchronous functions', 'Only Promises'], a: 1, e: 'promisify assumes the last argument is a callback of the form (err, result): it supplies its own callback, resolving with result and rejecting with err. Break that assumption and it fails quietly rather than loudly — a plain synchronous function returns a promise that never settles, and a callback that passes its value first makes the promise reject with that value. "Any function" is the tempting answer; the one escape hatch is util.promisify.custom, which lets a library provide its own promise version.', intro: 'promisify passes in a callback of its own. Ask what it must be able to expect that callback to be called with.', tags: ['Node', 'Callbacks'] },
  { q: '`const readFile = util.promisify(fs.readFile);` What does `readFile(\'notes.txt\', \'utf8\')` return now?', opts: ['The file contents, synchronously', 'A Promise you can await', 'undefined until a callback is passed', 'An EventEmitter that emits \'data\''], a: 1, e: 'util.promisify wraps an error-first callback function so that it returns a Promise: the callback is supplied internally, the Promise fulfils with the callback\'s result and rejects with its error, so you can await it or chain .then. The work is still asynchronous, so the contents are not returned synchronously, and no callback or event listener is needed any more.', intro: 'promisify changes only the way the result is delivered, not the work itself. Ask what the wrapped function hands back the moment you call it.', tags: ['Node', 'Callbacks'] },
  { q: 'In `fs.readFile(path, cb)`, what is the callback’s first argument?', opts: ['The file data', 'The error (or null)', 'The encoding', 'The path'], a: 1, e: 'Node uses error-first callbacks: the first argument is an Error (or null when the call succeeded) and the data comes second. On success err is null and data holds the contents; on failure, such as a missing file, err carries the error (for example err.code === \'ENOENT\') and data is undefined. The encoding and the path are inputs you pass to readFile, never callback arguments.', intro: 'The convention is named after whichever argument comes first. Recall the name Node\'s docs use for this callback style.', tags: ['Node', 'Callbacks'] },
  { q: 'Converting nested callbacks to Promises mainly improves:', opts: ['Raw execution speed', 'Readability and error flow', 'Memory usage', 'Startup time'], a: 1, e: 'Promises (and async/await on top of them) flatten the pyramid of nested callbacks and let one .catch or try/catch handle an error from any step, instead of checking err in every callback. The I/O itself is unchanged, so raw speed, memory use and startup time stay roughly the same; the gain is in maintainability and in errors that can no longer be forgotten.', intro: 'Ask what actually changes when the same I/O is expressed as a promise chain: the timing of the work, or the shape of the code around it?', tags: ['Node', 'Callbacks'] },
  { q: 'A callback that is accidentally invoked twice is:', opts: ['Normal and harmless', 'A bug: it must run exactly once', 'Required by stream APIs', 'How retries are implemented'], a: 1, e: 'The contract of a callback is that it is called exactly once, with either an error or a result. Calling it twice (a classic slip is calling cb(err) and then falling through to cb(null, data)) makes the caller send two responses or double-count, and after promisify the second call is silently ignored because a Promise can settle only once. Streams report repeated data through separate events, and retries are implemented by calling the operation again, not by re-invoking its callback.', intro: 'Picture what the caller does inside the callback: sends a response, resolves a promise, writes a file. Ask how many times it expects to do that.', tags: ['Node', 'Callbacks'] },

  // ── Level 14 — Async / Await ───────────────────────────────────────────
  { q: 'What does an `async` function always return?', opts: ['undefined', 'A Promise', 'The awaited value directly', 'A callback'], a: 1, e: 'Calling an async function always yields a Promise: a plain return 42 becomes a Promise that fulfils with 42, return somePromise adopts that promise\'s outcome, a throw becomes a rejection, and no return statement gives a Promise of undefined. The caller never receives the value directly; it must await the result or use .then. A callback is never involved.', intro: 'Take an async function that ends with `return 42`. Ask what the caller holds immediately after calling it, before anything has been awaited.', tags: ['Node', 'Async'] },
  { q: 'What does `await` do?', opts: ['Blocks all threads', 'Pauses the async function until the promise settles', 'Cancels the promise', 'Creates a new thread'], a: 1, e: 'await suspends the async function (not the whole process) until the awaited promise resolves or rejects. The rest of the program keeps running while it is suspended, on the same thread: nothing is blocked, no new thread appears, and awaiting a promise never cancels it. If the promise rejects, the await throws, so wrap it in try/catch.', intro: 'Write an async function with an await, call it, and log a line right after the call. Ask which line prints first and what that says about who is waiting.', tags: ['Node', 'Async'] },
  { q: 'What happens when you `await` a rejected promise?', opts: ['It returns undefined', 'It throws, which you can catch', 'It retries', 'It is ignored'], a: 1, e: 'When the awaited promise rejects, await throws the rejection reason at that line, so the rest of the function is skipped unless a surrounding try/catch handles it (otherwise the async function\'s own promise rejects). The rejection is never turned into an undefined return value, nothing is retried, and it is not ignored: an unhandled rejection ends a Node process by default.', intro: 'A promise has two outcomes, and await has to surface both of them inside plain sequential code. Think about how a failure can be expressed there.', tags: ['Node', 'Async'] },
  { q: 'Inside an async function, which construct catches the rejection of an awaited call so the function can recover?', opts: ['Checking whether the awaited value is an Error object', 'A try/catch block around the await', 'An error-first callback passed to the awaited function', 'A finally block on its own'], a: 1, e: 'A rejected promise throws at the await, so a try/catch around it (or around a group of awaits) receives the error and lets the function recover or rethrow; calling .catch() on the promise is an equally valid alternative. The awaited value is never an Error object on failure, because the code after the await does not run; the function you await hands back a promise rather than reporting errors through a callback; and finally runs cleanup but does not catch anything.', intro: 'Ask how a rejection reaches your code when you await it: as a returned value, as a callback argument, or as something else.', tags: ['Node', 'Async'] },
  { q: 'How do you run several promises concurrently and wait for all?', opts: ['Await each call in turn inside a for loop', 'Promise.all([...])', 'Promise.race([...])', 'Promise.any([...])'], a: 1, e: 'Promise.all takes an array of already-started promises and resolves with all their values once every one has fulfilled (three 50 ms tasks finish in about 50 ms, not 150 ms); if any rejects, it rejects immediately with that reason. Awaiting inside a for loop starts each task only after the previous one finished, so it runs them in series. Promise.race settles with the first promise to settle and Promise.any with the first to fulfil, so neither waits for all.', intro: 'Start with when each promise is created. Awaiting one before creating the next makes the work serial, whatever combinator you use afterwards.', tags: ['Node', 'Async'] },
  { q: 'Using `await` inside a normal for-loop runs the iterations:', opts: ['Concurrently: every iteration starts before any finishes', 'Sequentially: each iteration waits for the previous one', 'Concurrently, but the results are delivered in order', 'Synchronously, blocking the event loop until all finish'], a: 1, e: 'An await suspends the whole function, including the loop, until that promise settles, so the next iteration (and its promise) is not started until the previous one finishes: three 50 ms awaits take about 150 ms. Nothing else is blocked; the event loop keeps serving other work. To run the iterations concurrently, create all the promises first (for example with map) and then await Promise.all.', intro: 'Ask what the loop body can do while an await inside it is pending: continue to the next iteration, or wait.', tags: ['Node', 'Async'] },
  { q: 'How does `Promise.allSettled` differ from `Promise.all`?', opts: ['It settles as soon as the first input promise settles', 'It waits for every input promise and never short-circuits on rejection', 'It starts the promises one after another instead of together', 'It rejects with an array of every rejection reason'], a: 1, e: 'Promise.allSettled waits for every input promise and always fulfills, giving one {status:"fulfilled", value} or {status:"rejected", reason} object per input, so one failure no longer discards the successes. Promise.all short-circuits: it rejects with the first rejection reason as soon as it appears, and the values that did resolve are dropped. Neither combinator changes when the work starts — both receive promises that are already running — so nothing becomes sequential, and allSettled never rejects because an input rejected.', intro: 'Picture three requests where the middle one fails. Ask what each combinator hands back in that case.', tags: ['Node', 'Async'] },
  { q: 'async/await is syntactic sugar over:', opts: ['Callbacks', 'Promises', 'Worker threads', 'EventEmitter events'], a: 1, e: 'An async function always returns a promise (returning 1 gives a promise that fulfills with 1, throwing gives a rejected promise), and await simply suspends the function until a promise settles, so you can await any thenable and still attach .then/.catch to the result of an async call. Callbacks are the older pattern async/await replaced — nothing is compiled into callbacks — and no thread is involved: await moves no work off the main thread, it only lets the current function yield while the event loop keeps running. EventEmitter is a separate one-to-many notification API, not the substrate for await.', intro: 'Ask what an async function hands back to its caller before its body has finished running — that object is what await is built to consume.', tags: ['Node', 'Async'] },

  // ── Level 15 — Environment & CLI ───────────────────────────────────────
  { q: 'How do you read an environment variable named API_KEY?', opts: ['process.get("API_KEY")', 'process.env.API_KEY', 'env("API_KEY")', 'global.API_KEY'], a: 1, e: 'Node copies the process environment into process.env, a plain object of string values, so process.env.API_KEY (or process.env["API_KEY"]) reads it and yields undefined when the variable is not set. There is no process.get() and no global env() helper, and environment variables are never added to the global scope, so global.API_KEY is undefined. Note that every value is a string: process.env.PORT is "3000", not 3000, so compare and convert accordingly.', intro: 'Ask where Node keeps the environment: merged into the global scope, or as one object hanging off process?', tags: ['Node', 'CLI'] },
  { q: 'What is `process.argv[0]`?', opts: ['The first user argument', 'The path to the node executable', 'The path to the script being run', 'The current working directory'], a: 1, e: 'process.argv is the whole command line: index 0 is process.execPath, the absolute path of the node binary; index 1 is the absolute path of the script; and everything you typed after that starts at index 2, which is why CLI code uses process.argv.slice(2). The script path is argv[1], not argv[0], and the working directory never appears in argv at all — that is process.cwd().', intro: 'Learners expect their own arguments at index 0. Write out the full command line and ask what sits in front of them.', tags: ['Node', 'CLI'] },
  { q: 'What is `process.argv[2]`?', opts: ['The node path', 'The script path', 'The first user-supplied argument', 'Always undefined'], a: 2, e: 'The first argument the user passes appears at index 2 of process.argv.', tags: ['Node', 'CLI'] },
  { q: 'How do you set an env var inline on Unix when running a script?', opts: ['node app.js --PORT 3000', 'PORT=3000 node app.js', 'set PORT=3000 node app.js', 'export PORT = 3000 node app.js'], a: 1, e: 'In a POSIX shell a NAME=value prefix sets that variable in the environment of the command it prefixes only, so PORT=3000 node app.js makes process.env.PORT the string "3000" and leaves your shell session unchanged. node app.js --PORT 3000 passes an argument instead: it lands in process.argv, not process.env. set PORT=3000 is Windows cmd syntax and does not chain a command that way, and export takes no spaces around = and would leak the variable into the rest of the session. For cross-platform npm scripts use cross-env or Node’s --env-file.', intro: 'Decide whether the value should arrive in process.argv or in process.env, then pick the syntax the shell applies to just this one command.', tags: ['Node', 'CLI'] },
  { q: 'Are `.env` files loaded automatically by Node by default?', opts: ['Yes, Node reads .env from the working directory at startup', 'No, you must pass --env-file or load it with a package such as dotenv', 'Only when NODE_ENV=production is set', 'Only for ES modules, not for CommonJS'], a: 1, e: 'Running node app.js never reads .env, so process.env.FOO stays undefined until you either pass the built-in flag — node --env-file=.env app.js, added in Node 20.6 and no longer experimental as of 22.21 — or call a loader such as dotenv at the top of your program. Nothing here depends on NODE_ENV or on the module system: the file is ignored in every environment and for both CommonJS and ESM. With --env-file, a missing file throws, which is usually what you want in a deployment.', intro: 'Many frameworks and tools load .env for you. Ask whether that convenience comes from the runtime itself or from something you added.', tags: ['Node', 'CLI'] },
  { q: 'An exit code of 0 from a process conventionally means:', opts: ['That the process failed', 'That the process succeeded', 'That the process was killed by a signal', 'That the process produced no output'], a: 1, e: 'By POSIX convention a process exits with 0 when it succeeded and with a non-zero code when it failed, which is why cmd1 && cmd2 runs the second command only after a 0 and why CI marks a step failed on anything else. Because there is one success value and many failure values, 0 cannot also stand for "no output" — a program can succeed and print nothing — and a process killed by a signal reports 128 plus the signal number in most shells. In Node you signal failure with process.exit(1) or, better, by setting process.exitCode = 1 and letting the process end naturally.', intro: 'Learners read 0 as false. Ask whether an exit status is a boolean, or a code where each non-zero value names a different failure.', tags: ['Node', 'CLI'] },
  { q: 'Which stream does a Node program read from when input is typed at a terminal, piped in, or redirected from a file?', opts: ['process.stdout', 'process.stdin', 'process.stderr', 'console.input'], a: 1, e: 'process.stdin is the readable stream on file descriptor 0, so it delivers whatever is fed to the program: keystrokes in a terminal, the left side of a pipe such as cat data.txt | node app.js, or a redirected file. process.stdout (fd 1) and process.stderr (fd 2) are writable — you write results and diagnostics to them and cannot read from them — and there is no console.input. To read a line interactively, use node:readline on top of process.stdin.', intro: 'Two of the three standard streams are writable and only one is readable. Work out which direction data flows for each before you pick.', tags: ['Node', 'CLI'] },
  { q: 'What is `NODE_ENV` commonly set to?', opts: ['"debug" or "release"', '"production" or "development"', '"true" or "false"', '"local" or "remote"'], a: 1, e: 'By convention NODE_ENV names the environment the app is running in, and the exact string "production" is what tooling checks: Express, for example, then caches compiled views and stops sending stack traces to clients, and many libraries drop development-only checks. Node itself never reads NODE_ENV — it has no built-in meaning — which is why a typo such as "Production", or leaving it unset, silently gives you development behavior on a production server. It is neither a boolean nor a build flavor, so values like "true" or "release" are just strings nothing recognizes.', intro: 'Ask what a deployment needs this value for: telling one running environment from another, or toggling a build flavor on and off?', tags: ['Node', 'CLI'] },

  // ── Level 16 — npm & package.json ──────────────────────────────────────
  { q: 'What does the package.json "scripts" field define?', opts: ['Dependencies', 'Named commands runnable via npm run', 'The license', 'The author'], a: 1, e: '"scripts" maps a name to a shell command, so npm run build executes whatever "build" holds. npm puts node_modules/.bin on PATH while it runs, which is why a script can call jest or tsc with no global install; "start", "test", "stop" and "restart" also work without the run keyword. "dependencies", "license" and "author" are package.json fields too, but they are metadata npm reads — none of them is executable.', intro: 'Recall the commands a project README tells you to run after cloning. Ask which package.json field makes those work.', tags: ['Node', 'npm'] },
  { q: 'How do dependencies differ from devDependencies?', opts: ['There is no practical difference between them', 'devDependencies are needed only to develop, build or test the package', 'devDependencies are installed too when someone installs your package', 'dependencies are installed only at build time, devDependencies at runtime'], a: 1, e: 'Both lists are installed when you run npm install inside the project itself, so the difference is who else gets them: only dependencies are installed transitively for anyone who installs your package, and only they survive npm ci --omit=dev in a production image. Test runners, bundlers, linters and type definitions therefore belong in devDependencies. Getting it backwards either ships build tooling into production — a larger image and more supply-chain surface — or leaves a module the running code needs uninstalled.', intro: 'Picture someone running npm install your-package inside their own project. Ask which of the two lists they must download for your code to run.', tags: ['Node', 'npm'] },
  { q: 'You want jest available to `npm test` in this project but not installed in production. Which command records that?', opts: ['npm install jest', 'npm install jest --save-dev', 'npm install -g jest', 'npm install jest --no-save'], a: 1, e: 'npm install jest --save-dev (or -D) records jest under devDependencies, so npm ci installs it for tests while npm ci --omit=dev leaves it out of a production image. Plain npm install jest writes it to dependencies, which ships a test runner to production. -g installs it globally and writes nothing to package.json, so a teammate cloning the repo would not get it, and --no-save installs it without recording it at all — the next clean install would lose it.', intro: 'All four of these install something. Ask which one writes jest into the list a production install is allowed to skip.', tags: ['Node', 'npm'] },
  { q: 'What is package-lock.json for?', opts: ['It lists the version ranges your project asks for', 'It records the exact resolved version of every installed package', 'It caches the package files so installs work offline', 'It tells npm which files to publish'], a: 1, e: 'package.json records ranges such as ^1.2.3; the lockfile records the one version each range actually resolved to — for every transitive dependency — with its resolved URL and integrity hash, so npm ci rebuilds exactly the tree you tested. Without it a fresh install can pick a newer matching version, which is how CI breaks while your machine still works. It is not a package cache (npm keeps that in its own cache directory), holds no secrets, and does not control publishing — that is the "files" field or .npmignore.', intro: 'package.json says which versions are acceptable. Ask what a second machine needs so it installs the same tree you tested, not merely an acceptable one.', tags: ['Node', 'npm'] },
  { q: 'What does the "main" field in package.json specify?', opts: ['The test command', 'The package’s entry-point module', 'The author', 'The Node version'], a: 1, e: '"main" names the file Node loads when code imports the package by name with no subpath, so require("mylib") resolves to it instead of falling back to index.js. In a modern package the "exports" field takes precedence over "main" whenever it is present, and it also blocks deep imports of files you did not list, so "main" is the fallback for older tooling and CommonJS consumers. The test command lives in scripts.test, the supported Node range in "engines" and the author in "author" — none of those affects module resolution.', intro: 'Ask what Node has to decide when an import names only the package, with no path after it.', tags: ['Node', 'npm'] },
  { q: 'What does the version range `^1.2.3` allow?', opts: ['Only the exact version 1.2.3', '>=1.2.3 and <2.0.0', '>=1.2.3 and <1.3.0', '>=1.2.3, including 2.x releases'], a: 1, e: 'A caret allows any update that does not change the left-most non-zero part of the version, so ^1.2.3 accepts 1.2.4 and 1.9.0 but stops before 2.0.0, where semver permits breaking changes. ~1.2.3 is the tighter range that stops at 1.3.0, and an exact pin is written 1.2.3 or installed with --save-exact. Watch the 0.x exception: there the left-most non-zero part is the minor, so ^0.2.3 means >=0.2.3 <0.3.0, not <1.0.0.', intro: 'Compare `^` with `~` on the same version. Ask how much of the number each one is willing to let change.', tags: ['Node', 'npm'] },
  { q: 'What does `npm ci` do?', opts: ['Installs the newest versions your ranges allow and updates the lockfile', 'Deletes node_modules and installs exactly what the lockfile pins', 'Runs the project’s continuous-integration tests', 'Installs only the packages missing from node_modules'], a: 1, e: 'npm ci removes node_modules and installs the exact tree the lockfile pins. It never writes package.json or package-lock.json and it fails outright when the two disagree, which is what makes a CI build reproducible and catches a lockfile someone forgot to commit. npm install is the opposite: it may resolve new versions inside your ranges, update the lockfile, and top up only what is missing. The name is misleading — ci runs no tests; its own aliases, npm clean-install and npm install-clean, describe it better.', intro: 'The two install commands differ in what they are allowed to change. Ask which one is never permitted to rewrite the lockfile.', tags: ['Node', 'npm'] },
  { q: 'What lives in the node_modules folder?', opts: ['Your own source files, copied there by npm', 'The installed packages, including every transitive dependency', 'Only the packages listed in your package.json', 'The bundled build npm produces from your code'], a: 1, e: 'node_modules holds what npm installed: your direct dependencies and every package those depend on, hoisted into a mostly flat tree, plus the executables in node_modules/.bin that npm scripts call. It is generated output, fully reproducible from package.json and the lockfile, so it belongs in .gitignore and can be deleted and rebuilt with npm ci whenever it looks wrong. Your own source stays where you put it, and npm writes no build output there.', intro: 'Compare the number of folders in node_modules with the number of entries in your dependencies list.', tags: ['Node', 'npm'] },

  // ── Level 17 — Error Handling ──────────────────────────────────────────
  { q: 'Throwing inside an async function causes the returned promise to:', opts: ['Resolve with undefined', 'Reject with that error', 'Throw synchronously to the caller', 'Stay pending until something handles it'], a: 1, e: 'An async function returns its promise immediately, so a throw in the body cannot reach the caller synchronously — it settles that promise as rejected with the thrown value. That is why try { doWork() } catch {} around an un-awaited call catches nothing, while try { await doWork() } catch (e) {} and doWork().catch(...) both work. A rejection nobody handles does not hang either: since Node 15 an unhandled rejection is raised as an uncaught exception and terminates the process.', intro: 'Ask when the caller receives the promise object, relative to when the function body actually runs and throws.', tags: ['Node', 'Errors'] },
  { q: 'Which event fires on a synchronous uncaught exception?', opts: ['process.on("exit")', 'process.on("uncaughtException")', 'process.on("error")', 'process.on("crash")'], a: 1, e: 'process emits "uncaughtException" when a synchronous throw reaches the top of the stack with no try/catch anywhere; the handler receives the error and its origin, and it is the last point at which you can record what happened. "exit" also fires, but on every shutdown, clean or not, and it cannot tell you why. There is no "crash" event, and "error" is the EventEmitter convention used by streams, sockets and child processes, not a process-level hook for a bug in your code. Promise rejections have their own separate event.', intro: 'Distinguish the event that fires on every shutdown from the one that fires only because an error escaped the whole call stack.', tags: ['Node', 'Errors'] },
  { q: 'Which process event fires when a promise rejects and nothing has handled the rejection?', opts: ['unhandledRejection', 'rejection', 'promiseError', 'asyncError'], a: 0, e: 'process emits "unhandledRejection" when a promise rejects and no rejection handler — a .catch, the second argument of .then, or an await inside a try — is attached by the end of that turn; the handler receives the reason and the promise itself. Since Node 15 a rejection you leave unhandled is then raised as an uncaught exception and the process exits non-zero, so this hook is for logging before shutdown, not for keeping a broken process running. The other three names are invented: Node pairs "unhandledRejection" with "uncaughtException", and the EventEmitter "error" event is a different mechanism entirely.', intro: 'All four names sound plausible. Ask which one you have actually seen Node print when a service died from a rejected promise.', tags: ['Node', 'Errors'] },
  { q: 'What does a try/catch block catch?', opts: ['Only errors thrown directly in the try block, not in functions it calls', 'Synchronous throws and rejections of promises you await', 'Errors passed to a callback, automatically', 'Any error in the process, including from timer callbacks'], a: 1, e: 'try/catch catches anything thrown while control is inside the block, including throws from functions called within it, and — because await resumes the function inside the block — the rejection of any promise you await. It does not catch what happens after the block returns: an error handed to a callback later (Node passes it as the callback’s first argument, and you must check it), a throw inside a setTimeout callback, or an un-awaited async call whose promise rejects. Those escape to process "uncaughtException" or "unhandledRejection" instead, which is why an await you forgot silently becomes a crash somewhere else.', intro: 'A try block covers code while control is inside it. Ask which of these errors happen later, after the block has already returned.', tags: ['Node', 'Errors'] },
  { q: 'How do you create a custom error type?', opts: ['throw "MyError: something failed"', 'class MyError extends Error { }', 'const MyError = new Error("MyError")', 'function MyError(message) { this.message = message }'], a: 1, e: 'Extending the built-in Error gives you a real type: new MyError(msg) is instanceof both MyError and Error, super(message) fills in message and stack, and setting this.name = "MyError" makes the stack header readable — so a caller can branch with if (err instanceof MyError) instead of matching on message text. Throwing a string throws a value with no stack and no type, so all context about where it happened is lost. new Error("MyError") creates one instance, not a type, and the old function MyError(...) pattern does not inherit from Error unless you wire the prototype up by hand.', intro: 'You want catch (e) to be able to ask what kind of failure this is. Ask which of these produces something instanceof can test against Error.', tags: ['Node', 'Errors'] },
  { q: 'What does `error.stack` contain?', opts: ['Only the message passed to the constructor', 'The name and message plus the call frames captured when the error was created', 'The call stack of the running function, updated as the error propagates', 'A machine-readable code identifying the error type'], a: 1, e: 'error.stack is a string whose first line is "Name: message" and whose remaining lines are the call frames V8 captured when the Error was constructed — not when it was thrown, and not updated as it propagates, so an error created in one function and thrown in another still points at the place it was created. Logging only error.message throws that context away; log the error itself or error.stack. A short machine-readable identifier is a different property: Node system errors carry error.code, such as ENOENT.', intro: 'Ask at which moment this property is filled in: when you write new Error(...), when you throw, or when a catch receives it.', tags: ['Node', 'Errors'] },
  { q: 'After an `uncaughtException`, the safest practice is to:', opts: ['Log it and carry on serving requests', 'Log it, clean up synchronously and exit', 'Reset the event loop and continue', 'Retry the operation that threw'], a: 1, e: 'Node’s documentation is explicit that it is not safe to resume normal operation after "uncaughtException": the throw unwound the stack from an arbitrary point, so half-finished work, open handles and module state may be inconsistent. The supported use is synchronous cleanup — flush a log line, close a descriptor — and then exit, letting a supervisor such as systemd, pm2 or your orchestrator start a fresh process. Continuing or retrying leaves a process that looks healthy while serving corrupted state, and there is no way to "reset" the event loop from inside it.', intro: 'The handler runs only after an error escaped every frame on the stack. Ask what you can still trust about the state it unwound.', tags: ['Node', 'Errors'] },
  { q: 'How do operational and programmer errors differ?', opts: ['They are two names for the same thing', 'Operational errors are expected runtime conditions; programmer errors are bugs in the code', 'Operational errors come from the OS; programmer errors come from libraries', 'Operational errors are always fatal; programmer errors are always recoverable'], a: 1, e: 'Operational errors are conditions a correct program must expect — a refused connection, a timeout, a missing file, invalid user input — so you plan a response: retry, fall back, or return a 4xx/5xx. Programmer errors are bugs such as reading a property of undefined or passing the wrong type; there is no sensible runtime response, so you let the process crash, read the stack and fix the code. The split is not about where the error came from — a library can raise either — and neither kind is always fatal; the test is whether a runtime response exists.', intro: 'Classify two failures: a refused TCP connection, and reading a property of undefined. Ask which one a bug-free program can still meet.', tags: ['Node', 'Errors'] },

  // ── Level 18 — Timers & Scheduling ─────────────────────────────────────
  { q: 'When does `setTimeout(fn, 0)` run fn?', opts: ['Immediately, before the next line runs', 'After the current synchronous code finishes, in the timers phase', 'After the current line but before any promise callbacks', 'Exactly 0 ms later, interrupting whatever is running'], a: 1, e: 'JavaScript runs to completion, so the callback cannot fire until the current synchronous code returns; it is queued and the loop runs it in the timers phase. Microtasks come first: promise callbacks and process.nextTick are drained before the loop reaches timers, so a Promise.resolve().then(...) scheduled after your setTimeout still runs before it. And 0 is a floor rather than a promise — Node clamps the delay to at least 1 ms, and a busy loop pushes it out much further.', intro: 'Nothing interrupts JavaScript that is already running. Ask what has to finish before the event loop can look at its timer queue at all.', tags: ['Node', 'Timers'] },
  { q: 'What does `setInterval` do?', opts: ['Runs once after a delay', 'Runs a callback repeatedly on an interval', 'Cancels a timer', 'Pauses execution'], a: 1, e: 'setInterval schedules the callback to run again roughly every N milliseconds until you stop it with clearInterval(id); a live interval also keeps the process alive, so a script that never clears one will not exit on its own. setTimeout is the run-once version and clearTimeout/clearInterval are what cancel — nothing here pauses execution, since the timer API has no blocking sleep. The interval spaces out the starts, not the finishes: if the callback awaits something slower than the interval, a second run begins before the first has finished, which is why polling loops usually chain setTimeout instead.', intro: 'Compare it with setTimeout: same two arguments, one difference in how many times the callback runs.', tags: ['Node', 'Timers'] },
  { q: 'What does `clearTimeout(id)` do?', opts: ['Runs the pending callback immediately', 'Cancels the timeout, and does nothing if it already fired', 'Pauses the timeout so it can be resumed later', 'Cancels every timeout scheduled by the process'], a: 1, e: 'clearTimeout(id) removes that one scheduled callback from the timer queue so it never runs; calling it after the timeout already fired, or twice on the same id, is a harmless no-op. Timers have no pause and resume — you cancel and schedule a new one — and the id identifies a single timeout, never all of them. Cancelling matters at teardown: a pending retry or debounce that fires after its socket closed does work against state that is gone, and until it fires or is cleared it also keeps the process alive.', intro: 'The id is a handle to one specific scheduled callback. Ask what can still be done to it, and what cannot be undone once it has run.', tags: ['Node', 'Timers'] },
  { q: 'How does `setImmediate` differ from `setTimeout(fn, 0)`?', opts: ['They are two names for the same function', 'setImmediate runs in the check phase, right after the poll (I/O) phase', 'setImmediate runs synchronously, before the current function returns', 'setImmediate runs only once the process has been idle for a whole loop'], a: 1, e: 'setImmediate queues its callback in the check phase, which the loop enters immediately after the poll phase where I/O callbacks run — so inside an I/O callback setImmediate always runs before a setTimeout(fn, 0), however many timers are pending. setTimeout(fn, 0) is an ordinary timer: it waits for the timers phase and its delay is clamped to at least 1 ms, which is why from the main module the two orders are not deterministic and depend on how long the process took to start. Neither is synchronous, and setImmediate does not wait for the process to become idle.', intro: 'Run both inside an fs.readFile callback and the order never changes; run both at the top level and it does. Ask what makes the difference.', tags: ['Node', 'Timers'] },
  { q: 'In a CommonJS module, relative to timers and promises, `process.nextTick` callbacks run:', opts: ['After timers but before promise callbacks', 'Before promise callbacks and before any timer', 'In one shared queue with promise callbacks, in scheduling order', 'Only once the event loop has no other work left'], a: 1, e: 'Node drains the nextTick queue first, then the promise microtask queue, and only then lets the loop advance to timers, I/O and check callbacks — so a nextTick callback runs before a Promise.resolve().then() that was scheduled earlier, and long before any setTimeout. They are two separate queues, not one queue in scheduling order. Because the loop cannot advance until nextTick is empty, code that keeps re-queuing process.nextTick starves all I/O and timers, which is why setImmediate is the safer default for "run after this turn". One exception worth knowing: at the top level of an ES module the module body runs inside a microtask, so a nextTick queued there runs after the promise callbacks queued beside it.', intro: 'Queue a nextTick, a promise callback and a 0 ms timer in one script and read the order the output comes out in.', tags: ['Node', 'Timers'] },
  { q: 'Do Node timers guarantee an exact delay?', opts: ['Yes, to the millisecond', 'No, the delay is only a minimum', 'Yes, unless the delay is under 1 ms', 'No, but the error stays under 1 ms'], a: 1, e: 'A delay is a threshold: the callback becomes eligible after that much time and actually runs when the loop next reaches the timers phase, so the real delay is at least what you asked for and often more. Node is single-threaded, so a synchronous block, a slow callback or a busy poll phase pushes every pending timer out — and a delay under 1 ms is clamped up to 1 ms rather than being exact. Never build a clock, a rate limit or a deadline out of accumulated setTimeout calls: read Date.now() or process.hrtime.bigint() when the callback actually runs.', intro: 'One thread runs every callback in turn. Ask what happens to a timer whose moment arrives while something else is still running.', tags: ['Node', 'Timers'] },
  { q: 'What does calling `.unref()` on a timer do?', opts: ['Cancels the timer', 'Stops the timer from keeping the process alive', 'Makes the timer fire sooner than its delay', 'Releases the callback so it can be garbage collected'], a: 1, e: 'Node keeps running while any referenced handle is outstanding, and a pending timer is one. unref() drops that reference: the callback still fires normally if the loop is alive when the delay elapses, but if the timer is the only thing left the process exits instead of waiting for it. It does not cancel the timer — that is clearTimeout — does not change the delay, and has nothing to do with garbage collection. Use it for background work such as a periodic health ping that should never hold a CLI or worker open; ref() restores the reference.', intro: 'Run a script whose only pending work is a 200 ms timer, then add .unref() and run it again. Ask what changed.', tags: ['Node', 'Timers'] },
  { q: 'What does `queueMicrotask(fn)` schedule?', opts: ['A callback in the next timers phase, like setTimeout(fn, 0)', 'A microtask, run after the current operation and before the loop continues', 'A callback in the check phase, like setImmediate(fn)', 'A callback that runs only when nothing else is pending'], a: 1, e: 'queueMicrotask(fn) puts fn on the same microtask queue promise reactions use, so it runs as soon as the current synchronous operation finishes and always before the loop moves on to timers, I/O or check callbacks — which is exactly why it is not the same as setTimeout(fn, 0) or setImmediate(fn), both of which wait for a loop phase. It is how you defer work by one turn without allocating a promise, and unlike process.nextTick it does not cut ahead of promise callbacks. Nothing here involves a thread: microtasks run on the same thread as the rest of your code.', intro: 'It shares a queue with something you already use every day. Ask when a .then callback runs relative to the code that scheduled it.', tags: ['Node', 'Timers'] },

  // ── Level 19 — Child Processes ─────────────────────────────────────────
  { q: 'Which module runs other programs or commands?', opts: ['cluster', 'child_process', 'worker_threads', 'net'], a: 1, e: 'child_process starts a separate operating-system process running any program — git, ffmpeg, a shell command or another Node script — and hands you its stdio and exit code. cluster also creates processes, but only copies of your own Node app sharing a listening socket, and worker_threads runs your JavaScript on threads inside the same process; neither can launch an external binary. net is the TCP module and starts no process at all.', intro: 'Two of these run your own JavaScript in parallel and one is the raw TCP module. Ask which can launch a binary that was never written in Node.', tags: ['Node', 'ChildProcess'] },
  { q: 'What does `exec(cmd, cb)` do?', opts: ['Streams output with no shell', 'Runs a command in a shell and buffers the output', 'Forks a Node process', 'Creates a thread'], a: 1, e: 'exec hands the whole command string to a shell (/bin/sh on Unix, cmd.exe on Windows), so pipes, globs, quoting and && all work, then collects everything the child printed and passes the complete stdout and stderr to the callback as strings once it exits. Both consequences matter: the output is held in memory, and any user input interpolated into that string can inject extra commands — pass arguments as an array to execFile or spawn when the input is not yours. Streaming without a shell is spawn, running another Node script over an IPC channel is fork, and no thread is involved in any of them.', intro: 'Compare it with spawn, which takes a program and an array of arguments. Ask what changes when you hand the whole line over as one string.', tags: ['Node', 'ChildProcess'] },
  { q: 'How does `spawn` differ from `exec`?', opts: ['spawn buffers all output and hands it over at the end', 'spawn streams output and uses no shell by default', 'spawn blocks until the child process exits', 'spawn returns a promise you can await'], a: 1, e: 'spawn returns a ChildProcess whose stdout and stderr are readable streams, so output is processed as it arrives and its size does not matter; exec waits for the child to exit and hands you one string. spawn also executes the file directly with no shell, and arguments are passed as an array that is never re-interpreted: spawn("echo", ["*.mjs"]) prints the literal *.mjs, and a shell string such as "echo a && echo b" fails with ENOENT unless you pass { shell: true }. That is what makes spawn the safe default for anything built from user input. It is asynchronous and returns a ChildProcess rather than a promise — the blocking forms are spawnSync and execSync.', intro: 'Picture a command that prints a gigabyte, and a command string assembled from user input. Ask which of the two survives both situations.', tags: ['Node', 'ChildProcess'] },
  { q: 'What does `fork` create?', opts: ['A new thread inside the current process', 'A new Node process with an IPC channel', 'A shell that runs the given command', 'A copy of the current process, sharing its memory'], a: 1, e: 'child_process.fork(modulePath) is spawn specialized for Node: it starts a brand-new node process running the module you name — fresh memory, its own event loop, a different pid — and wires up an IPC channel so parent and child can exchange messages. Despite the name it is not POSIX fork(2): none of the parent’s memory is copied and the child begins at the first line of your module. It is not a thread either (that is worker_threads, which shares the process) and it does not go through a shell (that is exec).', intro: 'The name is borrowed from POSIX, but Node’s version does not duplicate the running program. Ask what it starts instead.', tags: ['Node', 'ChildProcess'] },
  { q: 'How do a parent and a forked child communicate?', opts: ['Shared variables — both processes see the same objects', 'Messages: child.send/process.send, with a "message" event on each side', 'A file on disk that both processes poll', 'Command-line arguments only, fixed when the child starts'], a: 1, e: 'A forked child has its own memory, so the two sides exchange copies: the parent calls child.send(value), the child calls process.send(value), and each side receives the other’s messages through a "message" event — process.on("message") in the child, child.on("message") in the parent. Values are serialized, so functions and class instances do not survive the trip and mutating the object you sent changes nothing on the other side. Shared variables and global state cannot reach across a process boundary at all, and while argv can carry startup data it is one-way and fixed at launch.', intro: 'Two processes have separate memory, so nothing can be handed over by reference. Ask what form the data has to take to cross between them.', tags: ['Node', 'ChildProcess'] },
  { q: 'A risk of `exec` with very large output is:', opts: ['The command runs twice', 'Output past maxBuffer kills the child and the callback gets an error', 'The shell truncates the output silently and the callback succeeds', 'The output is written to a temporary file instead of memory'], a: 1, e: 'exec holds all of stdout and stderr in memory until the child exits, bounded by the maxBuffer option, which defaults to 1 MiB. When the child writes past it Node terminates the child and calls your callback with an error whose code is ERR_CHILD_PROCESS_STDIO_MAXBUFFER — it does not truncate silently and it does not spill to a file, so a command that behaves in testing starts failing once a log or a directory listing grows. Raising maxBuffer only moves the ceiling; for output of unknown size use spawn and read the stream as it arrives.', intro: 'exec keeps everything the child prints until it exits. Ask what has to give when that pile outgrows the limit Node puts on it.', tags: ['Node', 'ChildProcess'] },
  { q: 'What does `child_process.spawn(cmd, args)` return with the default stdio settings?', opts: ['The command\'s complete output as a string', 'A ChildProcess whose stdout and stderr are readable streams', 'A Buffer holding the command\'s stdout', 'Nothing; the output arrives only through a callback'], a: 1, e: 'spawn returns immediately with a ChildProcess object; with the default stdio: \'pipe\', its stdout and stderr are readable streams you consume as data arrives, and the \'close\' or \'exit\' events tell you when the command finished. A finished string or Buffer is what exec and execSync give you; spawn never collects output for you. spawn takes no completion callback, so \'nothing\' is wrong too.', intro: 'spawn returns before the command has written anything. Think about what a value returned at that moment can and cannot contain.', tags: ['Node', 'ChildProcess'] },
  { q: 'What does `execSync` do?', opts: ['Runs a command asynchronously and calls back with its buffered output', 'Runs a command synchronously and returns its stdout when it exits', 'Runs a command and streams its output through a ChildProcess', 'Forks a new Node process and opens an IPC channel to it'], a: 1, e: 'execSync blocks the event loop until the command exits and then returns its stdout, as a Buffer or as a string when you pass an encoding; a non-zero exit code makes it throw. exec does the same work asynchronously with a callback, spawn hands you streams while the command runs, and fork starts another Node process with an IPC channel. Because it blocks, execSync belongs in scripts and build steps, not in request handlers.', intro: 'The name ends in Sync. Decide what that says about when the call returns and where the output goes meanwhile.', tags: ['Node', 'ChildProcess'] },

  // ── Level 20 — Crypto ──────────────────────────────────────────────────
  { q: 'Which module provides cryptographic functions?', opts: ['hash', 'crypto', 'secure', 'cipher'], a: 1, e: 'The built-in crypto module (import crypto from \'node:crypto\') provides hashing (createHash), HMAC (createHmac), ciphers, key derivation (scrypt, pbkdf2) and secure randomness (randomBytes, randomUUID). hash, secure and cipher are not Node modules: require(\'node:hash\') fails with ERR_UNKNOWN_BUILTIN_MODULE, and without the prefix Node looks for a package of that name and fails with MODULE_NOT_FOUND. For code shared with browsers, globalThis.crypto exposes the Web Crypto API in Node as well.', intro: 'Recall the `node:` specifier you import to get createHash, createHmac and randomBytes; only one of these four names is a real built-in.', tags: ['Node', 'Crypto'] },
  { q: 'What does `crypto.randomUUID()` return?', opts: ['A timestamp', 'A random RFC 4122 v4 UUID string', 'A hash', 'A Buffer'], a: 1, e: 'crypto.randomUUID() returns a string such as 0828c618-ec2c-4694-98fd-84722fae47e9: a version-4 UUID whose random bits come from a cryptographic generator, which is why it is safe for identifiers and tokens. It is not a Buffer (that is randomBytes), it is not derived from the clock like a version-1 UUID, and it is not a hash of any input. The same function exists in browsers as globalThis.crypto.randomUUID().', intro: 'Settle two things: what shape the value has (string, Buffer, number) and where its randomness comes from.', tags: ['Node', 'Crypto'] },
  { q: 'What does `crypto.createHash("sha256")` create?', opts: ['A cipher', 'A hash object you update then digest', 'A random key', 'A certificate'], a: 1, e: 'createHash(\'sha256\') returns a Hash object: you feed data with update() as many times as needed (or pipe a stream into it) and finish with digest(), which returns the result once; calling digest() again throws. A cipher needs a key and comes from createCipheriv, random keys come from randomBytes or generateKey, and certificates are not produced by the hashing API.', intro: 'createHash takes an algorithm name but no key and no data. Ask what kind of object can exist before any data has been fed in.', tags: ['Node', 'Crypto'] },
  { q: 'Which statement describes a cryptographic hash function?', opts: ['It can be reversed to recover the input', 'It is one-way: the input cannot be recovered', 'It is a form of encryption', 'It gives a different digest on each call'], a: 1, e: 'A cryptographic hash maps any input to a fixed-size digest that is deterministic (the same input always gives the same digest) and one-way: there is no key and no inverse operation, so the input cannot be recovered from the digest. Encryption differs because it uses a key and is designed to be reversed by decryption. A different digest on each call is wrong too; if hashing were random it could not verify integrity or passwords.', intro: 'Ask two things about the same input hashed twice: do you get the same digest, and can anyone turn the digest back into the input?', tags: ['Node', 'Crypto'] },
  { q: 'What does `crypto.randomBytes(16)` give you?', opts: ['A predictable sequence', '16 cryptographically strong random bytes', 'A UUID', 'A hash'], a: 1, e: 'randomBytes(16) returns a Buffer of 16 bytes drawn from a cryptographically secure generator, so the values are unpredictable; that is what makes them usable for session tokens, salts and keys. Math.random is not suitable for those because its output can be predicted. A UUID is a formatted string from randomUUID, and a hash is derived from an input rather than random.', intro: 'The argument is a count. Decide what is being counted and whether the source is meant to be guessable.', tags: ['Node', 'Crypto'] },
  { q: 'What does an HMAC require that a plain hash does not?', opts: ['A longer input message', 'A secret key', 'A random salt', 'A signed certificate'], a: 1, e: 'An HMAC mixes a secret key into the hash computation, so only parties holding the key can produce or verify the tag; that is what turns a hash into a message authentication code, used for webhook signatures and signed cookies. A salt is public and only defeats precomputed tables; it authenticates nothing. Certificates belong to public-key infrastructure, and the input length is irrelevant.', intro: 'Anyone can compute a plain SHA-256 of a message. Ask what an attacker would have to know to produce a valid HMAC.', tags: ['Node', 'Crypto'] },
  { q: 'How should you store user passwords?', opts: ['A single salted SHA-256 digest per user', 'A slow, salted password hash such as Argon2id or bcrypt', 'AES encryption with a key kept on the server', 'Base64 encoding so the value is not readable at a glance'], a: 1, e: 'Stored passwords should go through a deliberately slow, salted password-hashing function; OWASP recommends Argon2id, then scrypt, bcrypt, or PBKDF2 with a high iteration count, and Node ships scrypt and pbkdf2 in the crypto module. A salted SHA-256 is still a fast hash, so an attacker holding the database can test billions of guesses per second. Encryption is reversible, so a leaked key exposes every password at once, and Base64 is not protection at all.', intro: 'Assume the database leaks. Ask how many guesses per second an attacker can test against each stored value, and whether they could reverse it instead.', tags: ['Node', 'Crypto'] },
  { q: 'What does `createHash("sha256").update(data).digest("hex")` return?', opts: ['The original data', 'The hash as a hex string', 'A Buffer of the input', 'A random value'], a: 1, e: 'digest(\'hex\') finalises the hash over everything passed to update() and returns the 32-byte SHA-256 result as a 64-character hexadecimal string; without an encoding argument it returns a Buffer instead. The input is never returned (a hash is one-way) and the result is deterministic, not random. After digest() the Hash object cannot be reused.', intro: 'Look at the argument passed to digest and ask what it is an encoding of: the input, or the finished result.', tags: ['Node', 'Crypto'] },

  // ── Level 21 — Express: Basics ─────────────────────────────────────────
  { q: 'What is Express?', opts: ['A database', 'A minimal web framework for Node', 'A template engine', 'A bundler'], a: 1, e: 'Express is a small, unopinionated web framework for Node: express() returns an app on which you register middleware and routes, and app.listen starts an HTTP server. It stores no data (a database such as PostgreSQL does), renders no templates by itself (it delegates to engines such as EJS or Pug through res.render), and bundles no client code (that is Vite or webpack). Express 5 is the current major version.', intro: 'Think about where in a Node backend you would import Express and what the `app` object it gives you is used for.', tags: ['Node', 'Express'] },
  { q: 'What is the documented way to create an Express app?', opts: ['new Express()', 'const app = express()', 'express.app()', 'createApp()'], a: 1, e: 'The express module\'s default export is a factory function; the documented call is `const app = express()`, which returns the application object with app.use, app.get and app.listen. Express exports no class and its docs never use new; express.app is undefined, and createApp is Vue\'s API rather than Express\'s. Helpers such as express.json() and express.Router() hang off the same exported function.', intro: 'Look at what `require(\'express\')` (or the default import) actually gives you before deciding how to call it.', tags: ['Node', 'Express'] },
  { q: 'What does `app.get("/", handler)` do?', opts: ['Sends a GET request', 'Registers a handler for GET requests to "/"', 'Starts the server', 'Adds middleware globally'], a: 1, e: 'app.get(\'/\', handler) registers handler to run for HTTP GET requests whose path matches \'/\'; a POST to the same path is not matched and gets a 404 unless another route handles it. The call sends nothing itself, which is the confusion with client libraries where get() performs a request. The server starts only with app.listen, and app.use is what mounts middleware for every method.', intro: 'Express is the server side. Ask whether this line does its work when the file loads or later, when a matching request arrives.', tags: ['Node', 'Express'] },
  { q: 'Which parameter list does Express pass to a regular (non-error) middleware function?', opts: ['(req, res)', '(req, res, next)', '(err, req, res, next)', '(app, req, res)'], a: 1, e: 'Express calls regular middleware with (req, res, next); next() passes control to the next matching middleware or route, and the function must either call it or end the response. A function declared with four parameters, (err, req, res, next), is treated as error-handling middleware and is skipped in the normal flow, which is why the arity matters. A (req, res) function only works as a terminal handler that always responds, and Express never passes the app itself to middleware.', intro: 'Middleware must be able to hand the request on to whatever is registered after it; ask which parameter makes that possible.', tags: ['Node', 'Express'] },
  { q: 'What does `app.listen(3000)` do?', opts: ['Defines a route', 'Starts the server listening on port 3000', 'Parses JSON', 'Adds middleware'], a: 1, e: 'app.listen binds the Express app to a port and starts accepting requests.', tags: ['Node', 'Express'] },
  { q: 'What does `express.json()` do?', opts: ['Sends JSON', 'Parses incoming JSON request bodies into req.body', 'Validates JSON', 'Stringifies responses'], a: 1, e: 'express.json() returns middleware that reads the raw request body when the Content-Type is application/json, parses it and assigns the object to req.body; in Express 5 req.body stays undefined until a body parser has run. It does not validate the shape of the data: malformed JSON is rejected with a 400, but a valid object of the wrong shape passes straight through. Sending JSON responses is res.json\'s job.', intro: 'It is passed to app.use, so it runs on incoming requests. Ask what a request carrying JSON looks like before anything has read its body.', tags: ['Node', 'Express'] },
  { q: 'What does calling `next()` in middleware do?', opts: ['Ends the response', 'Passes control to the next matching middleware/handler', 'Restarts the request', 'Throws an error'], a: 1, e: 'next() hands the request to the next matching middleware or route handler in registration order. A middleware that neither calls next() nor sends a response leaves the client waiting until it times out, a common bug. Calling next(err) with an argument skips ordinary handlers and goes to error-handling middleware. Ending the response is the job of res.send or res.end, not next().', intro: 'Picture the middleware stack as a queue of functions for one request. Ask what has to happen for the request to reach the function after this one.', tags: ['Node', 'Express'] },
  { q: 'What does `app.use(fn)` do?', opts: ['Defines a GET route', 'Mounts middleware that runs for matching requests', 'Starts the server', 'Sends a response'], a: 1, e: 'app.use(fn) mounts fn as middleware; with no path it runs for every request regardless of method, and with a path such as app.use(\'/api\', fn) it runs for /api and any path beneath it, such as /api/users, but not for /apix. Registration order is execution order, so a body parser mounted after a route is too late for that route: its handler runs first, without the parsed body. app.get defines a GET route only, app.listen starts the server, and responses are sent from inside handlers with res.send or res.json.', intro: 'Compare it with app.get: ask which HTTP methods and which paths app.use applies to when no path is given.', tags: ['Node', 'Express'] },

  // ── Level 22 — Express: Req & Res ──────────────────────────────────────
  { q: 'In Express, what is `req.params`?', opts: ['The query string', 'The named route parameters (e.g. :id)', 'The request body', 'The headers'], a: 1, e: 'req.params is the object of values captured from named segments of the route path: for app.get(\'/users/:id\') and a request to /users/42, req.params.id is the string \'42\'. Values after the ? are in req.query, a parsed body is in req.body, and headers are in req.headers. Params are always strings, so convert and validate them before use.', intro: 'Think about where a value like the 42 in /users/42 lives: in the path itself, after a ?, or in the body.', tags: ['Node', 'Express'] },
  { q: 'What is `req.query`?', opts: ['The route params', 'The parsed query-string parameters', 'The body', 'The cookies'], a: 1, e: 'req.query is an object built from the query string: /search?q=shark&page=2 gives { q: \'shark\', page: \'2\' }, and a repeated key becomes an array. In Express 5 the default parser is \'simple\' (Node\'s querystring, so bracket syntax such as b[x]=2 stays a flat key) and req.query is a read-only getter. The values are user-controlled strings, so validate them. Route params are req.params, the body is req.body, and cookies need cookie-parsing middleware.', intro: 'Find the part of a URL such as /search?q=shark&page=2 that the route path does not describe, and ask which request property receives it.', tags: ['Node', 'Express'] },
  { q: 'What is `req.body` (with a body parser)?', opts: ['The raw, unparsed request stream', 'The parsed request payload', 'The query-string parameters', 'The uploaded files only'], a: 1, e: 'With body-parsing middleware such as express.json() or express.urlencoded() mounted, req.body holds the parsed payload as a JavaScript object, for example { name: \'Ada\' } from a JSON POST. Without a parser it is undefined in Express 5, and the raw bytes are only available by reading req itself as a stream. Query-string values live in req.query, and uploaded files come from a multipart parser such as multer, in req.file or req.files.', intro: 'Compare it with req.query and req.params: which part of the HTTP message do those two never cover?', tags: ['Node', 'Express'] },
  { q: 'What does `res.json(obj)` do?', opts: ['Logs obj to the server console as JSON', 'Sends obj serialized as JSON with a JSON content type', 'Validates obj against a JSON schema before sending', 'Redirects the client to a URL read from obj'], a: 1, e: 'res.json(obj) runs JSON.stringify on the value, sets Content-Type: application/json; charset=utf-8 unless you set one already, and ends the response. It performs no schema validation and no logging, and redirects are res.redirect\'s job. res.send(obj) also serializes objects and arrays, but res.json states the intent and is the usual choice for APIs.', intro: 'It is a method on the response. Ask what must happen to a JavaScript object before it can travel over HTTP.', tags: ['Node', 'Express'] },
  { q: 'What does `res.status(404)` do?', opts: ['Sends the body', 'Sets the HTTP status code on the response', 'Ends the response', 'Logs an error'], a: 1, e: 'res.status(404) sets the status code of the pending response and returns res, so you chain a sending method: res.status(404).json({ error: \'Not found\' }). On its own it sends nothing and does not end the response; forgetting the send leaves the request hanging. Express 5 throws if the code is not an integer between 100 and 999, and nothing is logged.', intro: 'Notice that the call carries a number but no body. Ask whether anything can leave the server before a body or an explicit end is provided.', tags: ['Node', 'Express'] },
  { q: 'What does `res.send(data)` do?', opts: ['Streams a file from disk to the client', 'Sends the body and picks a Content-Type from its type', 'Queues data to send after the handler returns', 'Sends the body without setting any headers'], a: 1, e: 'res.send(data) writes the body and ends the response, choosing a Content-Type when none is set: a string becomes text/html, a Buffer application/octet-stream, and an object or array is serialized as JSON; it also sets Content-Length. Files are served with res.sendFile, the response goes out immediately rather than being queued, and headers are set, not skipped. For plain text call res.type(\'text\') first.', intro: 'res.send accepts a string, a Buffer or an object. Ask whether those bytes go out immediately, and which other helper serves a file from disk.', tags: ['Node', 'Express'] },
  { q: 'What does `res.redirect("/login")` do?', opts: ['Renders a page', 'Sends a redirect response (302 by default)', 'Throws', 'Sets a cookie'], a: 1, e: 'res.redirect(\'/login\') sends a response with status 302 Found and a Location: /login header and ends the response; the browser then requests /login itself. Pass a status first to change it, for example res.redirect(301, \'/login\') for a permanent move. It renders nothing (that is res.render), throws nothing, and cookies are set with res.cookie. Express 5 dropped the \'back\' shortcut; use req.get(\'Referrer\') || \'/\' instead.', intro: 'Ask what a response must contain for the browser to request a different URL on its own, and which status codes carry that instruction.', tags: ['Node', 'Express'] },
  { q: 'How do you define a route parameter for a user id?', opts: ['"/users/{id}"', '"/users/:id"', '"/users/[id]"', '"/users/*"'], a: 1, e: 'Express marks a named parameter with a colon: \'/users/:id\' matches /users/42 and puts \'42\' in req.params.id. The other spellings come from elsewhere. {id} is OpenAPI/Spring style; in Express 5 braces mean an optional literal segment, so \'/users/{id}\' matches /users/ and /users/id and captures nothing. [id] is Next.js file routing and Express 5 rejects it as an unescaped reserved character, and a bare * wildcard must now be named, as in \'/files/*splat\'.', intro: 'Recall how the captured value is read back (req.params.id) and which path character Express uses to mark a segment as a named capture.', tags: ['Node', 'Express'] },

  // ── Level 23 — Concurrency ─────────────────────────────────────────────
  { q: 'How does Node achieve concurrency for I/O?', opts: ['It starts one operating-system thread per incoming request', 'It runs JavaScript on one thread and lets a non-blocking event loop overlap I/O', 'It polls every open socket in a tight loop until data arrives', 'It runs each callback on its own worker thread'], a: 1, e: 'Node runs your JavaScript on a single thread and asks the operating system for non-blocking I/O; the event loop (libuv, using epoll, kqueue or IOCP) waits on many sockets at once and runs each callback when its data arrives, so thousands of connections overlap without a thread each. Thread-per-request is how classic servers such as Apache\'s worker MPM work, busy-polling would burn the CPU, and callbacks never get their own threads; only some file-system and crypto calls use a small libuv thread pool behind the scenes.', intro: 'Ask what a Node process is doing while a database query is in flight: waiting on that query, or free to handle other events.', tags: ['Node', 'Concurrency'] },
  { q: 'A request handler performs a long synchronous image calculation on Node’s main JavaScript thread. What happens to unrelated callbacks?', opts: ['They continue normally because every callback gets its own thread', 'They wait until the calculation releases the event loop', 'They run faster because the CPU stays active', 'They move to worker threads automatically'], a: 1, e: 'Node runs all JavaScript, including every timer and I/O callback, on one thread. While the image calculation occupies it the event loop cannot advance, so unrelated callbacks queue until the calculation returns and every client of that process waits. Callbacks never get their own thread and Node never moves code to worker threads on its own; you have to offload with worker_threads or a child process, or split the work into smaller chunks.', intro: 'Ask which thread the timer and I/O callbacks need in order to run, and who is holding it during the calculation.', tags: ['Node', 'Concurrency'] },
  { q: 'What does the `worker_threads` module enable?', opts: ['Starting extra Node processes that talk over IPC', 'Running JavaScript on additional threads inside the same process', 'Making one thread run several callbacks at the same time', 'Moving network I/O off the event loop onto threads'], a: 1, e: 'worker_threads starts additional V8 threads inside the same Node process; each worker runs its own JavaScript with its own event loop, communicates through postMessage, and can share memory through SharedArrayBuffer. That makes it the tool for CPU-heavy work such as parsing or image processing. child_process and cluster start separate processes with IPC, a single thread can never run two callbacks at once, and network I/O is already non-blocking on the event loop, so workers add nothing there.', intro: 'Contrast it with child_process.fork and ask what the word \'thread\' changes about isolation and memory.', tags: ['Node', 'Concurrency'] },
  { q: 'Which pair of asynchronous Node operations can use libuv’s worker pool rather than non-blocking network polling?', opts: ['setTimeout and Promise.then', 'fs.readFile and crypto.pbkdf2', 'HTTP socket reads and queueMicrotask', 'JSON.parse and an ordinary JavaScript loop'], a: 1, e: 'fs.readFile and crypto.pbkdf2 both run on libuv\'s worker pool: most operating systems have no non-blocking file API, and pbkdf2 is CPU-bound, so libuv executes them on one of its four default threads (UV_THREADPOOL_SIZE) and posts the result back. dns.lookup and asynchronous zlib calls use the pool as well. Timers, microtasks and queueMicrotask are event-loop bookkeeping, socket reads use the OS\'s non-blocking polling, and JSON.parse or a loop simply run on the main thread.', intro: 'Ask which of these operations the operating system cannot deliver as a non-blocking event, so libuv has to run a blocking call on a background thread instead.', tags: ['Node', 'Concurrency'] },
  { q: 'File and crypto jobs appear to saturate libuv’s worker pool. What should you do before increasing its size?', opts: ['Set a large fixed UV_THREADPOOL_SIZE in every environment so the pool never fills', 'Find which calls are queueing, then benchmark a bounded increase against that workload', 'Match the pool size to the CPU count, because extra threads never help beyond that', 'Switch the fs and crypto calls to their synchronous variants so they bypass the pool'], a: 1, e: 'More threads help only if the pool is the real bottleneck and the machine has spare cores. On a 4-CPU box, eight concurrent pbkdf2 calls took about 750 ms with UV_THREADPOOL_SIZE=1 and about 210 ms at the default 4, while raising it to 8 or 32 changed nothing, because the cores were already busy. So identify the queued operations (fs, zlib, dns.lookup, pbkdf2/scrypt) and test a bounded change against your own load and hardware. A fixed value set everywhere cannot match every machine, CPU count is not the rule for I/O-bound file work, and the synchronous variants skip the pool only by blocking the event loop instead.', intro: 'The pool serves fs, zlib, dns.lookup and some crypto calls. A file wait and a pbkdf2 burst load it in very different ways.', tags: ['Node', 'Concurrency'] },
  { q: 'What does the `cluster` module do?', opts: ['Starts extra threads inside one process that share the same heap', 'Forks worker processes with child_process.fork that share one listening port', 'Runs one process per request and recycles it after the response', 'Adds a reverse proxy that spreads requests across several machines'], a: 1, e: 'cluster spawns workers with child_process.fork() and hands them connections on a single shared listening port (round-robin by default everywhere except Windows), so one service can occupy every core: two forked workers answered the same 127.0.0.1:45123 with two different pids. Workers are separate processes with separate memory, so sessions and caches must live outside them. worker_threads is the option that adds threads inside one process, and cluster balances only within one machine, unlike a reverse proxy.', intro: 'Count how many operating-system processes exist afterwards, and ask who owns the socket they all answer on.', tags: ['Node', 'Concurrency'] },
  { q: 'What does a `SharedArrayBuffer` allow?', opts: ['Passing a buffer between threads without copying by transferring ownership', 'Giving several threads access to one memory region at the same time', 'Sharing memory between the separate processes that cluster forks', 'Holding binary data outside the V8 heap so it is never collected'], a: 1, e: 'A SharedArrayBuffer stays readable and writable from every thread that receives it, so no copy is made: a worker that incremented an Int32Array view turned 41 into 42 in the parent. A plain ArrayBuffer sent through workerData or postMessage is structured-cloned, so the parent still read 0 where the worker had written 9, and listing it in transferList moves it instead of sharing it. Coordinate access with Atomics; cluster workers are separate processes and cannot share memory this way.', intro: 'Send a buffer to a worker, have the worker write to it, then read it in the parent. Ask which kind of buffer shows the change.', tags: ['Node', 'Concurrency'] },
  { q: 'To keep the event loop responsive during heavy computation, you should:', opts: ['Wrap the computation in a Promise so it stops blocking the main thread', 'Move the computation to a worker thread or a child process', 'Raise UV_THREADPOOL_SIZE so libuv\'s pool absorbs the computation', 'Replace the async fs calls with synchronous ones so the work finishes sooner'], a: 1, e: 'CPU-bound JavaScript owns the single main thread, so every timer and I/O callback waits behind it: a 300 ms busy loop delayed a 10 ms timer by 290 ms, while the same loop inside a Worker delayed it by none. worker_threads (same process, can share memory) and child_process or cluster (separate processes) both give the work its own thread of execution. A promise only queues a callback on the same thread, libuv\'s pool runs its own C++ tasks and never your JavaScript, and synchronous fs blocks the loop harder still.', intro: 'Your JavaScript runs on one thread. Ask what would actually have to change for that loop to execute somewhere else.', tags: ['Node', 'Concurrency'] },

  // ── Level 24 — Testing & Debugging ─────────────────────────────────────
  { q: 'What is Node’s built-in test runner module?', opts: ['node:assert', 'node:test', 'node:jest', 'node:spec'], a: 1, e: 'node:test is the built-in runner, Stable in Node 22, and it resolves only with the node: prefix — a bare require(\'test\') fails. It provides test/describe/it, subtests, mocking and reporters, and `node --test` discovers files such as *.test.js without any dependency. node:assert is real but supplies only assertions, while node:jest and node:spec do not exist: requiring them throws ERR_UNKNOWN_BUILTIN_MODULE.', intro: 'Node ships the runner and the assertion helpers as two different modules. Two of these four names are not built-in modules at all.', tags: ['Node', 'Testing'] },
  { q: 'Which built-in module gives you checks that throw an AssertionError when they fail?', opts: ['console, through console.assert', 'assert, through strictEqual and deepStrictEqual', 'util, through util.isDeepStrictEqual', 'expect, a global Node provides for tests'], a: 1, e: 'node:assert is the assertion module: strictEqual, deepStrictEqual, throws and rejects raise an AssertionError, which is what makes a test fail under node --test or any runner. console.assert(false) only prints \'Assertion failed\' to stderr and continues, util.isDeepStrictEqual returns a boolean you would still have to act on, and there is no built-in expect global in Node — that one comes from Jest.', intro: 'One of these prints its failure and carries on, one hands back a boolean, and one is not part of Node at all.', tags: ['Node', 'Testing'] },
  { q: 'What does running with `node --inspect` enable?', opts: ['Prints a full stack trace on every uncaught exception', 'Opens the V8 inspector port so DevTools or an IDE can attach', 'Re-runs the process with source maps and verbose logging', 'Pauses execution on the first line until a debugger connects'], a: 1, e: '--inspect activates the V8 inspector on 127.0.0.1:9229 and prints \'Debugger listening on ws://127.0.0.1:9229/…\'; the process then speaks the Chrome DevTools Protocol, so Chrome DevTools, VS Code or another IDE can attach while the program runs normally. The variant that stops before the first line is --inspect-brk. The flag changes nothing about optimization, logging or NODE_ENV, and it binds to localhost precisely because an open inspector port is remote code execution.', intro: 'Pass the flag to a one-line script and watch two things: what Node prints on stderr, and whether the script\'s own output still appears.', tags: ['Node', 'Debugging'] },
  { q: 'Where does `console.error` write?', opts: ['stdout, the same stream console.log uses', 'stderr, a stream separate from console.log', 'stderr only when the output is not a terminal', 'A log file that Node opens at startup'], a: 1, e: 'console.error writes to process.stderr and console.log to process.stdout: running the script with 2>/dev/null printed only \'LOG-line\', and with 1>/dev/null only \'ERR-line\'. That split is what lets you pipe a program\'s real output into a file or another command while diagnostics stay visible, and it is why log collectors can treat the two streams differently. Node writes to both whether or not the output is a terminal, and it opens no log file of its own.', intro: 'Redirect only stdout to a file and see which of the two messages is still on your terminal.', tags: ['Node', 'Debugging'] },
  { q: 'Which of these npm packages runs your test files and provides its own assertions and mocks?', opts: ['Nodemon', 'Jest', 'ESLint', 'c8'], a: 1, e: 'Jest is a test framework: it finds test files, runs them and ships expect() assertions, mocking and coverage in one package. Nodemon only restarts a process when files change, ESLint analyzes source without executing it, and c8 records coverage for tests that some other runner executes. Node\'s own node:test now covers much of the same ground without a dependency.', intro: 'Ask which one you would invoke to execute a *.test.js file and get pass/fail output, not to watch or measure it.', tags: ['Node', 'Testing'] },
  { q: 'Code calls `console.time("parse")`, parses a file, then calls `console.timeEnd("parse")`. What does Node report?', opts: ['The heap memory allocated while parsing', 'The elapsed duration between the matching calls', 'The CPU time used by every process on the machine', 'Only the time spent waiting for network operations'], a: 1, e: 'console.time stores a timestamp under the label and console.timeEnd prints the wall-clock difference to stdout — here \'parse: 119.089ms\' for a 120 ms section. Wall clock counts everything that happened in between, including time spent waiting on I/O, so it is neither CPU time nor a memory figure and it is not restricted to network calls. Labels must match: console.timeEnd(\'never-started\') prints a \'No such label\' warning instead of a duration. For numbers you want to keep, use performance.now() or perf_hooks rather than console output.', intro: 'The label is only a key. Ask what Node has to record at the first call so the second call can print anything.', tags: ['Node', 'Debugging'] },
  { q: 'What comparison does `assert.strictEqual(actual, expected)` use?', opts: ['==, after coercing the two values to one type', 'Object.is, which reports NaN as equal to NaN', '===, which reports NaN as different from NaN', 'A recursive comparison of the values\' own properties'], a: 1, e: 'Node defines strictEqual as testing equality \'as determined by Object.is()\', which is SameValue rather than ===. The difference is visible in exactly two places: assert.strictEqual(NaN, NaN) passes although NaN === NaN is false, and assert.strictEqual(0, -0) throws an AssertionError although 0 === -0 is true. Coercing == is what the legacy assert.equal uses, and recursive property comparison is deepStrictEqual — which also compares primitives with Object.is.', intro: 'Ask what the assertion does when both sides are NaN, and when one side is 0 and the other -0.', tags: ['Node', 'Testing'] },
  { q: 'A good tool for investigating a memory leak is:', opts: ['Raising --max-old-space-size until the process stops crashing', 'Comparing two heap snapshots taken as the process grows', 'Restarting the process on a timer so memory never builds up', 'Calling global.gc() after each request to force collection'], a: 1, e: 'A leak is found by comparing snapshots: capture one from a warm process and another after the load that grows memory — v8.writeHeapSnapshot(), or the Memory tab of DevTools attached through --inspect — then inspect the objects added between them and their retaining paths. Raising --max-old-space-size or restarting on a timer only postpones the crash and hides the retainer. Forcing global.gc() proves nothing, because leaked memory is still reachable and the collector is correct to keep it.', intro: 'A leaking object is still reachable, so the collector is right to keep it. Ask what would show you which reference is holding it.', tags: ['Node', 'Debugging'] },

  // ── Level 25 — Mixed Mastery ───────────────────────────────────────────
  { q: 'Which call blocks the event loop?', opts: ['fs.readFile', 'fs.readFileSync', 'fs.promises.readFile', 'fs.createReadStream'], a: 1, e: 'fs.readFileSync reads on the main thread and returns the data, so nothing else runs until it finishes: behind a 120 MB readFileSync a 10 ms timer fired 58 ms late, against 5 ms behind fs.promises.readFile and 1 ms behind createReadStream. The other three hand the work to libuv\'s thread pool and deliver it later through a callback, a promise or \'data\' events, leaving the loop free. Sync variants are fine while loading configuration at startup; on a request path they stall every other client.', intro: 'Look at what each call hands back the moment it returns: the file\'s contents, or some way to receive them later.', tags: ['Node', 'Mastery'] },
  { q: 'Inside a running CommonJS process, how do you make the next `require` of a module re-evaluate it instead of returning the cached exports?', opts: ['Call require twice; the second call re-runs the file', 'delete require.cache[require.resolve(path)] before requiring it again', 'Import it with a dynamic import(), which does not cache', 'Edit the file on disk; Node notices and re-reads it'], a: 1, e: 'require caches a module\'s exports under its resolved path, so a second require hands back the identical object; deleting that entry makes the next require re-run the file — two requires returned the same value, and the one after the delete returned a new one. That is how watchers and REPL reloads work, but it is a development trick: anything that already holds a reference keeps the old exports. Editing the file changes nothing for a module already loaded, and dynamic import() has its own module cache with no supported way to clear it.', intro: 'Node keeps each evaluated module under its resolved filename. Ask what has to happen to that entry.', tags: ['Node', 'Mastery'] },
  { q: 'Which works in both Node and the browser?', opts: ['process', 'globalThis', '__dirname', 'window'], a: 1, e: 'globalThis is defined by the language (ES2020), so it resolves to the global object in Node, in browsers, in web workers and in other runtimes, which is what makes it safe in code shared between server and client. process and __dirname exist only in Node — and __dirname only in CommonJS files, where ESM uses import.meta.dirname or import.meta.url. window exists only in a browser\'s main thread, not even in a worker; in Node, typeof window is \'undefined\'.', intro: 'One of these was added to the language precisely because every host had invented its own name for the global object.', tags: ['Node', 'Mastery'] },
  { q: 'Streaming a large file instead of readFile mainly improves:', opts: ['The total bytes read from the disk', 'The peak memory held while processing the file', 'The time until the last byte has been read', 'The number of system calls the process makes'], a: 1, e: 'createReadStream hands the file over in chunks that are collected once handled, so only a small window is resident: reading a 200 MB file lifted peak RSS about 40 MB above the process baseline through a stream, against about 200 MB with fs.promises.readFile, which materializes one 200 MB Buffer. Peak memory is what decides whether several concurrent large files fit in a container\'s limit. The same bytes still leave the disk, streaming makes more syscalls rather than fewer, and it does not shorten the total read — what it improves is when the first chunk can be processed.', intro: 'createReadStream hands over 64 KB at a time; readFile resolves with one Buffer holding everything. Ask what that changes and what it does not.', tags: ['Node', 'Mastery'] },
  { q: 'A function schedules a `setImmediate` and then a `process.nextTick` in the same synchronous block. Which callback runs first?', opts: ['setImmediate', 'process.nextTick', 'Whichever of the two was scheduled first', 'setImmediate, unless both are scheduled inside an I/O callback'], a: 1, e: 'The nextTick queue is drained as soon as the current operation finishes, before the event loop advances, so nextTick wins even though setImmediate was scheduled first — the run logged nextTick, then a promise microtask, then setImmediate. setImmediate belongs to the check phase, a full turn of the loop away, and that ordering does not change inside an I/O callback. It is also why a recursive nextTick can starve the loop, and why Node\'s own guidance prefers setImmediate for deferring work.', intro: 'Registration order is not the rule here. Ask where each of the two queues sits relative to the loop\'s phases.', tags: ['Node', 'Mastery'] },
  { q: 'Which actually controls a CommonJS module’s exports?', opts: ['exports', 'module.exports', 'export default', 'global'], a: 1, e: 'require() returns whatever module.exports refers to when the file finishes executing. `exports` is only a local variable initialized to that same object, so exports.foo = 1 works, but `exports = { a: 1 }` repoints the local and leaves module.exports untouched: requiring such a file returned {}, while the module.exports version returned { a: 1 }. `export default` is ESM syntax and is a SyntaxError in a CommonJS file, and `global` is process-wide state, not a module\'s public surface.', intro: 'One of the two is a local variable that starts out pointing at the other. Ask what reassigning it can change.', tags: ['Node', 'Mastery'] },
  { q: 'To run independent async tasks together and collect every result, use:', opts: ['A for…of loop that awaits each call in turn', 'Promise.all on an array of the promises', 'Promise.race on an array of the promises', 'Promise.any on an array of the promises'], a: 1, e: 'Promise.all waits for every promise and resolves with an array in input order: three independent 150 ms jobs finished in 150 ms, while awaiting them one at a time took 452 ms. It rejects as soon as any input rejects, so reach for Promise.allSettled when you need every outcome including the failures. Promise.race and Promise.any settle on a single result — the first to settle, and the first to fulfill — so neither gives you all three values.', intro: 'Ask how many of the results each of these hands back, and how long it waits before doing so.', tags: ['Node', 'Mastery'] },
  { q: 'An EventEmitter emits "error" with no listener attached. What happens?', opts: ['It is dropped, like any event with no listener', 'Node throws the error, usually crashing the process', 'It is queued until a listener is added later', 'Node logs the error and the process continues'], a: 1, e: '\'error\' is the one event name EventEmitter special-cases: with no \'error\' listener, emit(\'error\', err) throws that error, which becomes an uncaught exception and ends the process by default — emitting \'ping\' with no listener simply returns false and is dropped. So attach an \'error\' handler to every stream, socket and emitter you own, and use events.errorMonitor when you want to observe errors without counting as the handler. Nothing is buffered for a listener that arrives later, and Node does not merely log it.', intro: 'Compare it with emitting any other event name that has no listener; only one of the two is special-cased.', tags: ['Node', 'Mastery'] },
];
